    persona: Persona,
    anchor: string,
    kind: SuggestionKind,
  ): Promise<boolean> => {
    const client =
      auth.value.provider === "convex" && auth.value.user
        ? clientSig.value
        : null;
    const draftText = await readCurrentDraftText();
    const readiness = draftReadiness(draftText, MIN_MARKUP_WORDS);
    if (!readiness.ok) {
      store.conveneError = localDraftValidationError("propose-fix");
      return false;
    }
    if (!anchor.trim()) return false;

    let replacement = anchor;
    let rationale = "";

    // ── Try client-side AI first (BYOK) ─────────────────────────
    // Read at the action boundary: another tab or the Settings route may
    // have switched BYOK off since this panel was hydrated.
    const settings = normalizeAiSettings(await loadAiSettingsFromIdb());
    store.aiSettings = settings;
    const hasByok = hasConfiguredAiProvider(settings);
