        const onGlobalKeydown = (e: KeyboardEvent) => {
          const target = e.target as HTMLElement | null;
          const editingField =
            !!target &&
            (target.matches("input, textarea, select") ||
              (target.isContentEditable && !target.closest(".ProseMirror")));
          const key = e.key.toLowerCase();
          // Tab indents only in the manuscript. On a button, link or panel
          // it is how keyboard writers move between controls.
          const tabOutsideText =
            key === "tab" && !target?.closest(".ProseMirror");

          if (
            !editingField &&
            !tabOutsideText &&
            !e.defaultPrevented &&
            !store.typstSourcePending &&
            (!store.typstView || store.typstView === "write")
          ) {
            const matched = EDITOR_KEYBINDINGS.find((binding) =>
              chordMatches(
                {
                  key,
                  metaKey: e.metaKey,
                  ctrlKey: e.ctrlKey,
                  altKey: e.altKey,
                  shiftKey: e.shiftKey,
                },
                binding.shortcut,
              ),
            );
            if (matched) {
              e.preventDefault();
              window.dispatchEvent(
                new CustomEvent("twyne:editor-shortcut", {
                  detail: matched.commandId,
                }),
              );
              return;
            }
          }
          if (e.key !== "Escape") return;
          clearHoverTimer();
          noteHover.cancel();
          threadRequest.value++;
          store.selectionAction = null;
          if (store.notePopover) store.notePopover = null;
          if (store.userCommentPopover) store.userCommentPopover = null;
          if (store.suggestionPopover) store.suggestionPopover = null;
          if (store.openPicker) store.openPicker = null;
          store.showFindReplace = false;
          store.showOutline = false;
        };
        window.addEventListener("keydown", onGlobalKeydown);

