/* ── In-flow tools: the margins ──────────────────────────────
 * Right margin holds the one live tool, level with its passage;
 * left margin holds the writer's kept tools and the working ticks.
 * Both scroll with the page because they live inside the canvas. */
.twyne-in-flow-span {
  background-image: linear-gradient(
    to top,
    color-mix(in srgb, var(--color-cobalt) 38%, transparent) 1px,
    transparent 1px
  );
  background-repeat: no-repeat;
  background-size: 100% 100%;
}
.twyne-in-flow-sentence {
  background-color: color-mix(in srgb, var(--color-cobalt) 14%, transparent);
  border-radius: 2px;
}
.in-flow-rails {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}
.in-flow-rails > * {
  pointer-events: auto;
}
.in-flow-rail {
  position: absolute;
  left: calc(100% + 28px);
  transition: top 180ms ease-out;
}
.in-flow-connector {
  position: absolute;
  left: 100%;
  width: 28px;
  height: 0;
  border-top: 1px dashed
    color-mix(in srgb, var(--color-cobalt) 55%, transparent);
  pointer-events: none;
}
    transition: none;
  }
}
