import {
  $,
  component$,
  useSignal,
  useStore,
  useVisibleTask$,
} from "@qwik.dev/core";
import { api } from "../../../convex/_generated/api";
import { useAuth } from "../../utils/auth-context";
import { useConvexClient } from "../../utils/convex-context";
import { loadAiSettingsFromIdb } from "../../utils/idb";
import {
  hasConfiguredAiProvider,
  runClientAlternatives,
} from "../../utils/ai-client";
import { normalizeApplicationError } from "../../utils/application-errors";
import {
  alternativesPrompt,
  LENS_LABELS,
  LENSES_FOR,
  lexiconQueries,
  MAX_MODEL_ROUNDS,
  mergeOptions,
  MODEL_LENSES_FOR,
  parseAlternatives,
  parseLexicon,
  parsePartsOfSpeech,
  partOfSpeechQuery,
  roundSize,
  wordDelta,
  type AlternativeLens,
  type AlternativeOption,
  type AlternativesRequest,
} from "../../utils/alternatives";
import { sentenceWordDiff } from "../../utils/sentence-bench";
import {
  ALTERNATIVES_EVENT,
  ALTERNATIVES_STEP_EVENT,
  alternativesController,
  alternativesSnapshot,
  type AlternativesSnapshot,
} from "./extensions/alternatives";

type Filter = "all" | AlternativeLens;
type Fetching = "idle" | "loading" | "done" | "unavailable" | "error";

interface PaletteState {
  snapshot: AlternativesSnapshot | null;
  options: AlternativeOption[];
  /** null: the original is selected. */
  activeId: string | null;
  filter: Filter;
  lexicon: Fetching;
  model: Fetching;
  rounds: number;
  message: string;
}

/** Results kept per locked span, so reopening the same words costs nothing. */
interface CachedBrowse {
  options: AlternativeOption[];
  rounds: number;
  model: Fetching;
  lexicon: Fetching;
}
const browseCache = new Map<string, CachedBrowse>();
const cacheKey = (s: AlternativesSnapshot) =>
  JSON.stringify([s.scale, s.text, s.before.slice(-80), s.after.slice(0, 80)]);
function remember(key: string, value: CachedBrowse) {
  browseCache.delete(key);
  browseCache.set(key, value);
  while (browseCache.size > 24)
    browseCache.delete(browseCache.keys().next().value!);
}

const LEXICON_TIMEOUT_MS = 4500;
const PALETTE_WIDTH = 368;

/** The order lenses appear in under "All". */
function lensRank(lens: AlternativeLens, scale: AlternativesSnapshot["scale"]) {
  const order = LENSES_FOR[scale];
  const i = order.indexOf(lens);
  return i < 0 ? order.length : i;
}

function visibleOptions(state: PaletteState): AlternativeOption[] {
  const snapshot = state.snapshot;
  if (!snapshot) return [];
  if (state.filter !== "all")
    return state.options.filter((o) => o.lens === state.filter);
  if (snapshot.scale !== "word") return state.options;
  // Words read best grouped: synonyms, then antonyms, then slot fillers.
  return [...state.options].sort(
    (a, b) => lensRank(a.lens, "word") - lensRank(b.lens, "word"),
  );
}

function placement(snapshot: AlternativesSnapshot) {
  const { anchor } = snapshot;
  const vw = typeof window === "undefined" ? 1024 : window.innerWidth;
  const vh = typeof window === "undefined" ? 768 : window.innerHeight;
  const width = Math.min(PALETTE_WIDTH, vw - 16);
  const center = (anchor.left + anchor.right) / 2;
  const left = Math.max(8, Math.min(vw - width - 8, center - width / 2));
  const below = vh - anchor.bottom;
  const above = anchor.top;
  const goBelow = below >= 260 || below >= above;
  const room = Math.max(160, (goBelow ? below : above) - 20);
  return {
    left,
    width,
    top: goBelow ? anchor.bottom + 10 : undefined,
    bottom: goBelow ? undefined : vh - anchor.top + 10,
    maxHeight: Math.min(440, room),
  };
}

export const AlternativesPalette = component$<{ disabled?: boolean }>(
  (props) => {
    const auth = useAuth();
    const client = useConvexClient();
    const root = useSignal<HTMLDivElement>();
    const list = useSignal<HTMLDivElement>();
    const state = useStore<PaletteState>({
      snapshot: null,
      options: [],
      activeId: null,
      filter: "all",
      lexicon: "idle",
      model: "idle",
      rounds: 0,
      message: "",
    });

    const stillOn = (id: string) => state.snapshot?.id === id;

    const save = $(() => {
      const s = state.snapshot;
      if (!s) return;
      remember(cacheKey(s), {
        options: state.options,
        rounds: state.rounds,
        model: state.model === "loading" ? "idle" : state.model,
        lexicon: state.lexicon === "loading" ? "idle" : state.lexicon,
      });
    });

    const add = $((id: string, incoming: AlternativeOption[]) => {
      if (!stillOn(id) || !incoming.length) return;
      state.options = mergeOptions(state.options, incoming);
    });

    const fetchLexicon = $(async (snapshot: AlternativesSnapshot) => {
      if (snapshot.scale !== "word") return;
      state.lexicon = "loading";
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), LEXICON_TIMEOUT_MS);
      const get = async (url: string): Promise<unknown> => {
        const res = await fetch(url, { signal: controller.signal });
        if (!res.ok) throw new Error(`Datamuse ${res.status}`);
        return res.json();
      };
      try {
        const queries = lexiconQueries(snapshot);
        const [parts, ...bodies] = await Promise.allSettled([
          get(partOfSpeechQuery(snapshot.text)),
          ...queries.map((q) => get(q.url)),
        ]);
        if (!stillOn(snapshot.id)) return;
        const pos =
          parts.status === "fulfilled" ? parsePartsOfSpeech(parts.value) : [];
        let found: AlternativeOption[] = [];
        bodies.forEach((body, i) => {
          if (body.status !== "fulfilled") return;
          const query = queries[i]!;
          const parsed = parseLexicon(body.value, query, snapshot.text, pos);
          found = mergeOptions(
            found,
            parsed.slice(0, query.lens === "antonym" ? 10 : 18),
          );
        });
        await add(snapshot.id, found);
        if (stillOn(snapshot.id))
          state.lexicon = bodies.some((b) => b.status === "fulfilled")
            ? "done"
            : "error";
      } catch {
        if (stillOn(snapshot.id)) state.lexicon = "error";
      } finally {
        clearTimeout(timer);
        if (stillOn(snapshot.id)) await save();
      }
    });

    const fetchModel = $(
      async (snapshot: AlternativesSnapshot, lenses: AlternativeLens[]) => {
        if (state.model === "loading" || state.rounds >= MAX_MODEL_ROUNDS)
          return;
        state.model = "loading";
        state.message = "";
        const request: AlternativesRequest = {
          text: snapshot.text,
          before: snapshot.before,
          after: snapshot.after,
          scale: snapshot.scale,
          lenses,
          count: roundSize(snapshot.scale, state.rounds),
          exclude: [snapshot.text, ...state.options.map((o) => o.text)],
        };
        const id = snapshot.id;
        state.rounds++;
        let added = 0;
        const take = async (options: AlternativeOption[]) => {
          const before = state.options.length;
          await add(id, options);
          added += state.options.length - before;
        };
        try {
          const settings = await loadAiSettingsFromIdb();
          if (!stillOn(id)) return;
          if (settings && hasConfiguredAiProvider(settings)) {
            const { system, prompt } = alternativesPrompt(request);
            const text = await runClientAlternatives(
              {
                system,
                prompt,
                scale: snapshot.scale,
                onText: (partial) => {
                  if (!stillOn(id)) return;
                  void take(
                    parseAlternatives(partial, request, { partial: true }),
                  );
                },
              },
              settings,
            );
            if (!stillOn(id)) return;
            if (text === null) {
              state.model = "error";
              state.message =
                "Your model did not answer. Check the provider in Settings, or try again.";
              return;
            }
            await take(parseAlternatives(text, request));
          } else if (
            auth.value.provider === "convex" &&
            auth.value.user &&
            client.value
          ) {
            const result = await client.value.action(api.alternatives.suggest, {
              text: request.text,
              before: request.before,
              after: request.after,
              scale: request.scale,
              lenses: request.lenses,
              count: request.count,
              exclude: request.exclude.slice(0, 40),
            });
            if (!stillOn(id)) return;
            await take(result.options as AlternativeOption[]);
          } else {
            state.rounds--;
            state.model = "unavailable";
            return;
          }
          if (!stillOn(id)) return;
          state.model = "done";
          if (!added && state.rounds > 1)
            state.message = "No new wordings this time.";
        } catch (error) {
          if (!stillOn(id)) return;
          state.model = "error";
          state.message = normalizeApplicationError(error, {
            source: "provider",
            metadata: { feature: "alternatives" },
          }).message;
        } finally {
          if (stillOn(id)) await save();
        }
      },
    );

    const begin = $(async (snapshot: AlternativesSnapshot) => {
      const cached = browseCache.get(cacheKey(snapshot));
      state.snapshot = snapshot;
      state.options = cached?.options ?? [];
      state.rounds = cached?.rounds ?? 0;
      state.model = cached?.model ?? "idle";
      state.lexicon = cached?.lexicon ?? "idle";
      state.activeId = null;
      state.filter = "all";
      state.message = "";
      // Lexicon and model start together: lists arrive at once, the model's
      // in-context wordings stream in behind them.
      if (state.lexicon === "idle" || state.lexicon === "error")
        void fetchLexicon(snapshot);
      if (state.rounds === 0 || state.model === "error")
        void fetchModel(snapshot, MODEL_LENSES_FOR[snapshot.scale]);
    });

    const close = $((restoreSelection = true) => {
      alternativesController()?.preview(null);
      alternativesController()?.close({ restoreSelection });
    });

    const setActive = $((id: string | null) => {
      state.activeId = id;
      const option = id ? state.options.find((o) => o.id === id) : null;
      alternativesController()?.preview(option ? option.text : null);
      const row = list.value?.querySelector<HTMLElement>(
        `[data-option-id="${CSS.escape(id ?? "__original")}"]`,
      );
      row?.scrollIntoView({ block: "nearest" });
    });

    const use = $((option: AlternativeOption | null) => {
      if (!option) {
        void close();
        return;
      }
      const result = alternativesController()?.apply(option.text) ?? {
        ok: false as const,
        message: "The manuscript is no longer open. Copy the wording instead.",
      };
      if (!result.ok) state.message = result.message;
    });

    /** Near the end of the list: ask for more, within the lock's budget. */
    const maybeMore = $(async (index: number, length: number) => {
      const snapshot = state.snapshot;
      if (!snapshot || state.model !== "done") return;
      if (length - index > 2 || state.rounds >= MAX_MODEL_ROUNDS) return;
      await fetchModel(
        snapshot,
        state.filter === "all" ? MODEL_LENSES_FOR[snapshot.scale] : [state.filter],
      );
    });

    const step = $(async (delta: number) => {
      const options = visibleOptions(state);
      const ids = [null, ...options.map((o) => o.id)];
      const at = Math.max(0, ids.indexOf(state.activeId));
      const next = Math.max(0, Math.min(ids.length - 1, at + delta));
      await setActive(ids[next] ?? null);
      await maybeMore(next - 1, options.length);
    });

    const choose = $(async (filter: Filter) => {
      state.filter = filter;
      const snapshot = state.snapshot;
      if (!snapshot) return;
      const shown = visibleOptions(state);
      if (state.activeId && !shown.some((o) => o.id === state.activeId))
        await setActive(null);
      // A lens with nothing in it yet gets a round of its own.
      if (
        filter !== "all" &&
        !shown.length &&
        state.model !== "loading" &&
        state.model !== "unavailable" &&
        MODEL_LENSES_FOR[snapshot.scale].includes(filter)
      )
        await fetchModel(snapshot, [filter]);
    });

    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(({ cleanup }) => {
      const follow = (event: Event) => {
        const next = (event as CustomEvent<AlternativesSnapshot | null>).detail;
        if (!next) {
          void save();
          state.snapshot = null;
          state.options = [];
          state.activeId = null;
          return;
        }
        if (state.snapshot?.id === next.id) {
          // Same lock, new position (scroll, reflow while previewing).
          state.snapshot = next;
          return;
        }
        void begin(next).then(() => {
          requestAnimationFrame(() =>
            root.value
              ?.querySelector<HTMLElement>("[data-alternatives-list]")
              ?.focus({ preventScroll: true }),
          );
        });
      };
      const onStep = (event: Event) => {
        if (!state.snapshot) return;
        void step((event as CustomEvent<number>).detail);
      };
      const onPointer = (event: PointerEvent) => {
        if (!state.snapshot) return;
        const target = event.target as HTMLElement | null;
        if (
          target?.closest(".alternatives-palette") ||
          target?.closest("[data-alternatives-lock]") ||
          target?.closest(".ProseMirror")
        )
          return;
        void close(false);
      };
      window.addEventListener(ALTERNATIVES_EVENT, follow);
      window.addEventListener(ALTERNATIVES_STEP_EVENT, onStep);
      document.addEventListener("pointerdown", onPointer, true);
      const open = alternativesSnapshot();
      if (open) follow(new CustomEvent(ALTERNATIVES_EVENT, { detail: open }));
      cleanup(() => {
        window.removeEventListener(ALTERNATIVES_EVENT, follow);
        window.removeEventListener(ALTERNATIVES_STEP_EVENT, onStep);
        document.removeEventListener("pointerdown", onPointer, true);
      });
    });

    const snapshot = state.snapshot;
    if (!snapshot) return null;

    const lenses = LENSES_FOR[snapshot.scale];
    const options = visibleOptions(state);
    const counts = new Map<AlternativeLens, number>();
    for (const o of state.options)
      counts.set(o.lens, (counts.get(o.lens) ?? 0) + 1);
    const box = placement(snapshot);
    const loading = state.lexicon === "loading" || state.model === "loading";
    const activeIndex = state.activeId
      ? options.findIndex((o) => o.id === state.activeId)
      : -1;
    const word = snapshot.scale === "word";
    const budget =
      snapshot.words === 1
        ? "1 word"
        : `${snapshot.words} words`;
    const listId = `alternatives-list-${snapshot.id}`;
    const optionDomId = (id: string) =>
      `alternatives-option-${snapshot.id}-${id.replace(/[^\w-]/g, "_")}`;

    const empty = !options.length;
    const emptyText =
      state.model === "unavailable" && !word
        ? "Rewordings need a model. Connect one in Settings, or sign in to use Twyne's."
        : loading
          ? "Finding alternatives…"
          : state.filter !== "all"
            ? `No ${LENS_LABELS[state.filter].toLocaleLowerCase()} for this ${snapshot.scale}.`
            : "Nothing fits this slot yet.";

    return (
      <div
        ref={root}
        class={[
          "alternatives-palette",
          `alternatives-palette--${snapshot.scale}`,
        ]}
        style={{
          left: `${box.left}px`,
          width: `${box.width}px`,
          top: box.top === undefined ? undefined : `${box.top}px`,
          bottom: box.bottom === undefined ? undefined : `${box.bottom}px`,
          maxHeight: `${box.maxHeight}px`,
        }}
        role="dialog"
        aria-label={`Alternatives for “${snapshot.text.slice(0, 60)}”`}
        data-alternatives-palette={snapshot.id}
        onKeyDown$={(event) => {
          if (event.key === "Escape") {
            event.preventDefault();
            event.stopPropagation();
            void close();
          }
        }}
      >
        <header class="alternatives-palette__head">
          <p class="alternatives-palette__kicker">
            Alternatives <span aria-hidden="true">·</span>{" "}
            <span class="alternatives-palette__budget">
              {word ? "a word for this slot" : `about ${budget}`}
            </span>
          </p>
          <button
            type="button"
            class="alternatives-palette__close"
            aria-label="Keep the original and close"
            title="Keep the original (Esc)"
            onClick$={() => close()}
          >
            ×
          </button>
        </header>

        <div
          class="alternatives-palette__lenses"
          role="tablist"
          aria-label="Kinds of alternative"
        >
          {(["all", ...lenses] as Filter[]).map((lens) => {
            const n =
              lens === "all"
                ? state.options.length
                : (counts.get(lens as AlternativeLens) ?? 0);
            return (
              <button
                key={lens}
                type="button"
                role="tab"
                aria-selected={state.filter === lens}
                class={state.filter === lens ? "is-on" : ""}
                onClick$={() => choose(lens)}
              >
                {lens === "all" ? "All" : LENS_LABELS[lens as AlternativeLens]}
                {n > 0 && <span class="alternatives-palette__count">{n}</span>}
              </button>
            );
          })}
        </div>

        <div
          ref={list}
          id={listId}
          class="alternatives-palette__list"
          role="listbox"
          tabIndex={0}
          data-alternatives-list
          aria-label="Alternatives, original first"
          aria-activedescendant={
            state.activeId
              ? optionDomId(state.activeId)
              : `alternatives-option-${snapshot.id}-original`
          }
          onKeyDown$={(event) => {
            const key = event.key;
            if (key === "ArrowDown" || (key === "Tab" && !event.shiftKey && false)) {
              event.preventDefault();
              void step(1);
            } else if (key === "ArrowUp") {
              event.preventDefault();
              void step(-1);
            } else if (key === "PageDown") {
              event.preventDefault();
              void step(6);
            } else if (key === "PageUp") {
              event.preventDefault();
              void step(-6);
            } else if (key === "Home") {
              event.preventDefault();
              void setActive(null);
            } else if (key === "End") {
              event.preventDefault();
              void step(options.length);
            } else if (key === "ArrowRight" || key === "ArrowLeft") {
              event.preventDefault();
              const tabs = ["all", ...lenses] as Filter[];
              const at = tabs.indexOf(state.filter);
              const next =
                tabs[(at + (key === "ArrowRight" ? 1 : -1) + tabs.length) % tabs.length]!;
              void choose(next);
            } else if (key === "Enter") {
              event.preventDefault();
              void use(
                state.activeId
                  ? (state.options.find((o) => o.id === state.activeId) ?? null)
                  : null,
              );
            }
          }}
          onScroll$={(_, el) => {
            if (el.scrollTop + el.clientHeight >= el.scrollHeight - 24)
              void maybeMore(options.length - 1, options.length);
          }}
        >
          <div
            id={`alternatives-option-${snapshot.id}-original`}
            role="option"
            aria-selected={state.activeId === null}
            data-option-id="__original"
            class={[
              "alternatives-palette__option",
              "alternatives-palette__option--original",
              state.activeId === null ? "is-active" : "",
            ]}
            onMouseEnter$={() => setActive(null)}
            onClick$={() => use(null)}
          >
            <span class="alternatives-palette__text">{snapshot.text}</span>
            <span class="alternatives-palette__tag">original</span>
          </div>

          {options.map((option) => {
            const delta = wordDelta(option, snapshot.text);
            return (
              <div
                key={option.id}
                id={optionDomId(option.id)}
                role="option"
                aria-selected={state.activeId === option.id}
                data-option-id={option.id}
                class={[
                  "alternatives-palette__option",
                  state.activeId === option.id ? "is-active" : "",
                ]}
                onMouseEnter$={() => setActive(option.id)}
                onClick$={() => use(option)}
              >
                <span class="alternatives-palette__text">
                  {word
                    ? option.text
                    : sentenceWordDiff(snapshot.text, option.text)
                        .filter((part) => part.kind !== "removed")
                        .map((part, i) =>
                          part.kind === "added" ? (
                            <em key={i}>{part.text}</em>
                          ) : (
                            <span key={i}>{part.text}</span>
                          ),
                        )}
                </span>
                <span class="alternatives-palette__meta">
                  {(state.filter === "all" || word) && (
                    <span class="alternatives-palette__tag">
                      {word && option.source === "model"
                        ? option.lens === "synonym"
                          ? "fits here"
                          : LENS_LABELS[option.lens].toLocaleLowerCase()
                        : LENS_LABELS[option.lens].toLocaleLowerCase()}
                    </span>
                  )}
                  {!word && delta !== 0 && (
                    <span
                      class="alternatives-palette__delta"
                      title={`${Math.abs(delta)} ${Math.abs(delta) === 1 ? "word" : "words"} ${delta > 0 ? "longer" : "shorter"}`}
                    >
                      {delta > 0 ? `+${delta}` : `−${-delta}`}
                    </span>
                  )}
                </span>
              </div>
            );
          })}

          {empty && (
            <p class="alternatives-palette__empty" role="status">
              {emptyText}
            </p>
          )}
          {!empty && state.model === "loading" && (
            <p class="alternatives-palette__more" role="status">
              {state.rounds > 1 ? "Finding more…" : "Reading the sentence…"}
            </p>
          )}
          {!empty &&
            state.model === "done" &&
            state.rounds < MAX_MODEL_ROUNDS && (
              <button
                type="button"
                class="alternatives-palette__more alternatives-palette__more--button"
                onClick$={() =>
                  fetchModel(
                    snapshot,
                    state.filter === "all"
                      ? MODEL_LENSES_FOR[snapshot.scale]
                      : [state.filter],
                  )
                }
              >
                More
              </button>
            )}
        </div>

        {state.message && (
          <p class="alternatives-palette__notice" role="status">
            {state.message}
          </p>
        )}
        {state.model === "unavailable" && word && !empty && (
          <p class="alternatives-palette__notice">
            Word lists only. Connect a model in Settings for wordings that fit
            the sentence.
          </p>
        )}

        <footer class="alternatives-palette__keys" aria-hidden="true">
          <span>
            <kbd>↑</kbd>
            <kbd>↓</kbd> or scroll the locked words
          </span>
          <span>
            <kbd>↵</kbd> use
          </span>
          <span>
            <kbd>←</kbd>
            <kbd>→</kbd> kind
          </span>
          <span>
            <kbd>Esc</kbd> keep
          </span>
          {activeIndex >= 0 && (
            <span class="alternatives-palette__position">
              {activeIndex + 1}/{options.length}
            </span>
          )}
        </footer>
        {props.disabled && (
          <p class="alternatives-palette__notice">
            This manuscript is read-only.
          </p>
        )}
      </div>
    );
  },
);

