/**
 * The Alternatives palette: a list of replacements for the locked span,
 * anchored beside it. The option under the pointer or the keyboard stands in
 * for the locked words in the manuscript until the writer uses one (Enter or
 * a click) or keeps the original (Escape).
 *
 * It opens on its own work: word lists and the model's wordings are fetched
 * as soon as a lock appears, and more are fetched as the writer reaches the
 * end of the list, up to {@link MAX_MODEL_ROUNDS} model rounds per lock.
 */
import {
  $,
  component$,
  useSignal,
  useStore,
  useVisibleTask$,
} from "@qwik.dev/core";
import { api } from "../../../convex/_generated/api";
import { useAuth } from "../../utils/auth-context";
import { useConvexClient } from "../../utils/convex-context";
import { loadAiSettingsFromIdb } from "../../utils/idb";
import {
  hasConfiguredAiProvider,
  runClientAlternatives,
} from "../../utils/ai-client";
import { normalizeApplicationError } from "../../utils/application-errors";
import {
  alternativesPrompt,
  LENS_LABELS,
  LENSES_FOR,
  lexiconQueries,
  MAX_MODEL_ROUNDS,
  mergeOptions,
  MODEL_LENSES_FOR,
  parseAlternatives,
  parseLexicon,
  parsePartsOfSpeech,
  partOfSpeechQuery,
  roundSize,
  wordDelta,
  type AlternativeLens,
  type AlternativeOption,
  type AlternativesRequest,
} from "../../utils/alternatives";
import { sentenceWordDiff } from "../../utils/sentence-bench";
import {
  ALTERNATIVES_EVENT,
  ALTERNATIVES_STEP_EVENT,
  alternativesController,
  alternativesSnapshot,
  type AlternativesSnapshot,
} from "./extensions/alternatives";

type Filter = "all" | AlternativeLens;
type Fetching = "idle" | "loading" | "done" | "unavailable" | "error";

interface PaletteState {
  snapshot: AlternativesSnapshot | null;
  options: AlternativeOption[];
  /** null: the original is selected. */
  activeId: string | null;
  filter: Filter;
  lexicon: Fetching;
  model: Fetching;
  rounds: number;
  message: string;
}

// ── Per-span memory ─────────────────────────────────────────────────────
// Reopening the same words in the same place shows what was already found
// and spends nothing. Browser-only, bounded.

interface CachedBrowse {
  options: AlternativeOption[];
  rounds: number;
  model: Fetching;
  lexicon: Fetching;
}
const browseCache = new Map<string, CachedBrowse>();
const cacheKey = (s: AlternativesSnapshot) =>
  JSON.stringify([s.scale, s.text, s.before.slice(-80), s.after.slice(0, 80)]);
const settled = (f: Fetching): Fetching =>
  f === "loading" || f === "error" ? "idle" : f;

function remember(state: PaletteState) {
  const s = state.snapshot;
  if (!s) return;
  const key = cacheKey(s);
  browseCache.delete(key);
  browseCache.set(key, {
    options: state.options.map((o) => ({ ...o })),
    rounds: state.rounds,
    model: settled(state.model),
    lexicon: settled(state.lexicon),
  });
  while (browseCache.size > 24)
    browseCache.delete(browseCache.keys().next().value!);
}

function addOptions(
  state: PaletteState,
  id: string,
  incoming: AlternativeOption[],
): number {
  if (state.snapshot?.id !== id || !incoming.length) return 0;
  const before = state.options.length;
  state.options = mergeOptions(state.options, incoming);
  return state.options.length - before;
}

// ── View helpers ────────────────────────────────────────────────────────

const LEXICON_TIMEOUT_MS = 4500;
const PALETTE_WIDTH = 368;
const TABS = (s: AlternativesSnapshot) =>
  ["all", ...LENSES_FOR[s.scale]] as Filter[];

function visibleOptions(state: PaletteState): AlternativeOption[] {
  const snapshot = state.snapshot;
  if (!snapshot) return [];
  if (state.filter !== "all")
    return state.options.filter((o) => o.lens === state.filter);
  if (snapshot.scale !== "word") return state.options;
  // Words read best grouped: synonyms, then antonyms, then slot fillers.
  const order = LENSES_FOR.word;
  return [...state.options].sort(
    (a, b) => order.indexOf(a.lens) - order.indexOf(b.lens),
  );
}

function placement(snapshot: AlternativesSnapshot) {
  const { anchor } = snapshot;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const width = Math.min(PALETTE_WIDTH, vw - 16);
  const center = (anchor.left + anchor.right) / 2;
  const left = Math.max(8, Math.min(vw - width - 8, center - width / 2));
  const below = vh - anchor.bottom;
  const above = anchor.top;
  const goBelow = below >= 280 || below >= above;
  const room = Math.max(180, (goBelow ? below : above) - 24);
  return {
    left,
    width,
    top: goBelow ? anchor.bottom + 12 : undefined,
    bottom: goBelow ? undefined : vh - anchor.top + 12,
    maxHeight: Math.min(460, room),
  };
}

function tagFor(option: AlternativeOption, word: boolean): string {
  // At word scale the model's synonyms are the ones chosen for this
  // sentence; the lexicon's are the dictionary's.
  if (word && option.source === "model" && option.lens === "synonym")
    return "fits here";
  return LENS_LABELS[option.lens].toLocaleLowerCase();
}

const optionDomId = (lock: string, id: string | null) =>
  `alternatives-option-${lock}-${id ? id.replace(/[^\w-]/g, "_") : "original"}`;

export const AlternativesPalette = component$(() => {
  const auth = useAuth();
  const client = useConvexClient();
  const root = useSignal<HTMLDivElement>();
  const list = useSignal<HTMLDivElement>();
  const state = useStore<PaletteState>({
    snapshot: null,
    options: [],
    activeId: null,
    filter: "all",
    lexicon: "idle",
    model: "idle",
    rounds: 0,
    message: "",
  });

  const fetchLexicon = $(async (snapshot: AlternativesSnapshot) => {
    if (snapshot.scale !== "word") return;
    const on = () => state.snapshot?.id === snapshot.id;
    state.lexicon = "loading";
    const abort = new AbortController();
    const timer = setTimeout(() => abort.abort(), LEXICON_TIMEOUT_MS);
    const get = async (url: string): Promise<unknown> => {
      const res = await fetch(url, { signal: abort.signal });
      if (!res.ok) throw new Error(`Word list ${res.status}`);
      return res.json();
    };
    try {
      const queries = lexiconQueries(snapshot);
      const [parts, ...bodies] = await Promise.allSettled([
        get(partOfSpeechQuery(snapshot.text)),
        ...queries.map((q) => get(q.url)),
      ]);
      if (!on()) return;
      const pos =
        parts.status === "fulfilled" ? parsePartsOfSpeech(parts.value) : [];
      let found: AlternativeOption[] = [];
      bodies.forEach((body, i) => {
        if (body.status !== "fulfilled") return;
        const query = queries[i]!;
        const parsed = parseLexicon(body.value, query, snapshot.text, pos);
        found = mergeOptions(
          found,
          parsed.slice(0, query.lens === "antonym" ? 10 : 18),
        );
      });
      addOptions(state, snapshot.id, found);
      state.lexicon = bodies.some((b) => b.status === "fulfilled")
        ? "done"
        : "error";
    } catch {
      if (on()) state.lexicon = "error";
    } finally {
      clearTimeout(timer);
      if (on()) remember(state);
    }
  });

  const fetchModel = $(
    async (snapshot: AlternativesSnapshot, lenses: AlternativeLens[]) => {
      if (state.model === "loading" || state.rounds >= MAX_MODEL_ROUNDS)
        return;
      const id = snapshot.id;
      const on = () => state.snapshot?.id === id;
      state.model = "loading";
      state.message = "";
      const request: AlternativesRequest = {
        text: snapshot.text,
        before: snapshot.before,
        after: snapshot.after,
        scale: snapshot.scale,
        lenses,
        count: roundSize(snapshot.scale, state.rounds),
        exclude: state.options.map((o) => o.text).slice(0, 40),
      };
      state.rounds++;
      let added = 0;
      try {
        const settings = await loadAiSettingsFromIdb();
        if (!on()) return;
        if (settings && hasConfiguredAiProvider(settings)) {
          const { system, prompt } = alternativesPrompt(request);
          const text = await runClientAlternatives(
            {
              system,
              prompt,
              scale: snapshot.scale,
              onText: (partial) => {
                added += addOptions(
                  state,
                  id,
                  parseAlternatives(partial, request, { partial: true }),
                );
              },
            },
            settings,
          );
          if (!on()) return;
          if (text === null) {
            state.model = "error";
            state.message =
              "Your model did not answer. Check its provider in Settings, or press More to try again.";
            return;
          }
          added += addOptions(state, id, parseAlternatives(text, request));
        } else if (
          auth.value.provider === "convex" &&
          auth.value.user &&
          client.value
        ) {
          const result = await client.value.action(api.alternatives.suggest, {
            text: request.text,
            before: request.before,
            after: request.after,
            scale: request.scale,
            lenses: request.lenses,
            count: request.count,
            exclude: request.exclude,
          });
          if (!on()) return;
          added += addOptions(state, id, result.options);
        } else {
          state.rounds--;
          state.model = "unavailable";
          return;
        }
        state.model = "done";
        if (!added && state.rounds > 1)
          state.message = "No new wordings this time.";
      } catch (error) {
        if (!on()) return;
        state.model = "error";
        state.message = normalizeApplicationError(error, {
          source: "provider",
          metadata: { feature: "alternatives" },
        }).message;
      } finally {
        if (on()) remember(state);
      }
    },
  );

  const setActive = $((id: string | null) => {
    const snapshot = state.snapshot;
    if (!snapshot) return;
    state.activeId = id;
    const option = id ? state.options.find((o) => o.id === id) : null;
    alternativesController()?.preview(option ? option.text : null);
    document
      .getElementById(optionDomId(snapshot.id, id))
      ?.scrollIntoView({ block: "nearest" });
  });

  const close = $((restoreSelection: boolean) => {
    alternativesController()?.preview(null);
    alternativesController()?.close({ restoreSelection });
  });

  const use = $((id: string | null) => {
    const option = id ? state.options.find((o) => o.id === id) : null;
    if (!option) {
      alternativesController()?.preview(null);
      alternativesController()?.close({ restoreSelection: true });
      return;
    }
    const result = alternativesController()?.apply(option.text) ?? {
      ok: false as const,
      message: "The manuscript is no longer open.",
    };
    if (!result.ok) state.message = result.message;
  });

  /** Near the end of the list, ask for more within the lock's budget. */
  const more = $(async (remaining: number) => {
    const snapshot = state.snapshot;
    if (!snapshot || remaining > 2) return;
    if (state.model !== "done" || state.rounds >= MAX_MODEL_ROUNDS) return;
    await fetchModel(
      snapshot,
      state.filter === "all"
        ? MODEL_LENSES_FOR[snapshot.scale]
        : [state.filter],
    );
  });

  const step = $(async (delta: number) => {
    const options = visibleOptions(state);
    const ids = [null, ...options.map((o) => o.id)];
    const at = Math.max(0, ids.indexOf(state.activeId));
    const next = Math.max(0, Math.min(ids.length - 1, at + delta));
    await setActive(ids[next] ?? null);
    await more(ids.length - 1 - next);
  });

  const choose = $(async (filter: Filter) => {
    const snapshot = state.snapshot;
    if (!snapshot) return;
    state.filter = filter;
    const shown = visibleOptions(state);
    if (state.activeId && !shown.some((o) => o.id === state.activeId))
      await setActive(null);
    // A kind with nothing in it yet gets a model round of its own.
    if (
      filter !== "all" &&
      !shown.length &&
      (state.model === "done" || state.model === "idle") &&
      MODEL_LENSES_FOR[snapshot.scale].includes(filter)
    )
      await fetchModel(snapshot, [filter]);
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    const begin = (snapshot: AlternativesSnapshot) => {
      const cached = browseCache.get(cacheKey(snapshot));
      state.snapshot = snapshot;
      state.options = cached?.options.map((o) => ({ ...o })) ?? [];
      state.rounds = cached?.rounds ?? 0;
      state.model = cached?.model ?? "idle";
      state.lexicon = cached?.lexicon ?? "idle";
      state.activeId = null;
      state.filter = "all";
      state.message = "";
      // Lists and the model start together: the word lists land first, the
      // model's wordings for this sentence stream in behind them.
      if (state.lexicon === "idle") void fetchLexicon(snapshot);
      if (state.rounds === 0) void fetchModel(snapshot, MODEL_LENSES_FOR[snapshot.scale]);
      requestAnimationFrame(() =>
        list.value?.focus({ preventScroll: true }),
      );
    };
    const follow = (event: Event) => {
      const next = (event as CustomEvent<AlternativesSnapshot | null>).detail;
      if (!next) {
        remember(state);
        state.snapshot = null;
        state.options = [];
        state.activeId = null;
        return;
      }
      // Same lock, new position: the page scrolled.
      if (state.snapshot?.id === next.id) state.snapshot = next;
      else begin(next);
    };
    const onStep = (event: Event) => {
      if (state.snapshot) void step((event as CustomEvent<number>).detail);
    };
    // Native, so arrow keys and Enter are stopped before the list scrolls or
    // the editor's own shortcuts see them.
    const onKey = (event: KeyboardEvent) => {
      const snapshot = state.snapshot;
      const target = event.target as HTMLElement | null;
      if (!snapshot || !target?.closest?.(".alternatives-palette")) return;
      if (event.metaKey || event.ctrlKey || event.altKey) return;
      const key = event.key;
      const stop = () => {
        event.preventDefault();
        event.stopPropagation();
      };
      const onTab = target.getAttribute("role") === "tab";
      if (key === "Escape") {
        stop();
        void close(true);
      } else if (key === "ArrowDown") {
        stop();
        void step(1);
      } else if (key === "ArrowUp") {
        stop();
        void step(-1);
      } else if (key === "PageDown") {
        stop();
        void step(6);
      } else if (key === "PageUp") {
        stop();
        void step(-6);
      } else if (key === "Home" && !onTab) {
        stop();
        void setActive(null);
      } else if (key === "End" && !onTab) {
        stop();
        void step(state.options.length + 1);
      } else if (key === "ArrowRight" || key === "ArrowLeft") {
        stop();
        const tabs = TABS(snapshot);
        const at = tabs.indexOf(state.filter);
        const delta = key === "ArrowRight" ? 1 : -1;
        void choose(tabs[(at + delta + tabs.length) % tabs.length]!);
      } else if (key === "Enter" && !target.closest("button")) {
        stop();
        void use(state.activeId);
      }
    };
    const onPointer = (event: PointerEvent) => {
      if (!state.snapshot) return;
      const target = event.target as HTMLElement | null;
      // Clicks in the manuscript are the extension's to judge.
      if (
        target?.closest?.(".alternatives-palette") ||
        target?.closest?.(".ProseMirror")
      )
        return;
      void close(false);
    };
    window.addEventListener(ALTERNATIVES_EVENT, follow);
    window.addEventListener(ALTERNATIVES_STEP_EVENT, onStep);
    document.addEventListener("keydown", onKey, true);
    document.addEventListener("pointerdown", onPointer, true);
    const open = alternativesSnapshot();
    if (open) begin(open);
    cleanup(() => {
      window.removeEventListener(ALTERNATIVES_EVENT, follow);
      window.removeEventListener(ALTERNATIVES_STEP_EVENT, onStep);
      document.removeEventListener("keydown", onKey, true);
      document.removeEventListener("pointerdown", onPointer, true);
    });
  });

  const snapshot = state.snapshot;
  if (!snapshot) return null;

  const word = snapshot.scale === "word";
  const options = visibleOptions(state);
  const counts = new Map<AlternativeLens, number>();
  for (const o of state.options)
    counts.set(o.lens, (counts.get(o.lens) ?? 0) + 1);
  const box = placement(snapshot);
  const loading = state.lexicon === "loading" || state.model === "loading";
  const activeIndex = state.activeId
    ? options.findIndex((o) => o.id === state.activeId)
    : -1;
  const empty = !options.length;
  const emptyText =
    state.model === "unavailable" && !word
      ? "Rewordings need a model. Connect one in Settings, or sign in to use Twyne's."
      : loading
        ? "Finding alternatives…"
        : state.filter !== "all"
          ? `No ${LENS_LABELS[state.filter].toLocaleLowerCase()} for this ${snapshot.scale} yet.`
          : "Nothing fits this slot yet.";

  return (
    <div
      ref={root}
      class={["alternatives-palette", `alternatives-palette--${snapshot.scale}`]}
      style={{
        left: `${box.left}px`,
        width: `${box.width}px`,
        top: box.top === undefined ? undefined : `${box.top}px`,
        bottom: box.bottom === undefined ? undefined : `${box.bottom}px`,
        maxHeight: `${box.maxHeight}px`,
      }}
      role="dialog"
      aria-label={`Alternatives for “${snapshot.text.slice(0, 60)}”`}
      data-alternatives-palette={snapshot.id}
    >
      <header class="alternatives-palette__head">
        <p class="alternatives-palette__kicker">
          Alternatives
          <span class="alternatives-palette__budget">
            {word
              ? "for this word"
              : `about ${snapshot.words} words, like the original`}
          </span>
        </p>
        <button
          type="button"
          class="alternatives-palette__close"
          aria-label="Keep the original and close"
          title="Keep the original (Esc)"
          onClick$={() => close(true)}
        >
          ×
        </button>
      </header>

      <div
        class="alternatives-palette__lenses"
        role="tablist"
        aria-label="Kinds of alternative"
      >
        {TABS(snapshot).map((lens) => {
          const n =
            lens === "all"
              ? state.options.length
              : (counts.get(lens as AlternativeLens) ?? 0);
          return (
            <button
              key={lens}
              type="button"
              role="tab"
              tabIndex={-1}
              aria-selected={state.filter === lens}
              aria-controls={`alternatives-list-${snapshot.id}`}
              class={state.filter === lens ? "is-on" : ""}
              onClick$={() => choose(lens)}
            >
              {lens === "all" ? "All" : LENS_LABELS[lens as AlternativeLens]}
              {n > 0 && <span class="alternatives-palette__count">{n}</span>}
            </button>
          );
        })}
      </div>

      <div
        ref={list}
        id={`alternatives-list-${snapshot.id}`}
        class="alternatives-palette__list"
        role="listbox"
        tabIndex={0}
        aria-label="Alternatives, original first"
        aria-activedescendant={optionDomId(snapshot.id, state.activeId)}
        onScroll$={(_, el) => {
          if (el.scrollTop + el.clientHeight >= el.scrollHeight - 24)
            void more(0);
        }}
      >
        <div
          id={optionDomId(snapshot.id, null)}
          role="option"
          aria-selected={state.activeId === null}
          class={[
            "alternatives-palette__option",
            "alternatives-palette__option--original",
            state.activeId === null ? "is-active" : "",
          ]}
          onMouseEnter$={() => setActive(null)}
          onClick$={() => use(null)}
        >
          <span class="alternatives-palette__text">{snapshot.text}</span>
          <span class="alternatives-palette__meta">
            <span class="alternatives-palette__tag">original</span>
          </span>
        </div>

        {options.map((option) => {
          const delta = wordDelta(option, snapshot.text);
          return (
            <div
              key={option.id}
              id={optionDomId(snapshot.id, option.id)}
              role="option"
              aria-selected={state.activeId === option.id}
              class={[
                "alternatives-palette__option",
                state.activeId === option.id ? "is-active" : "",
              ]}
              onMouseEnter$={() => setActive(option.id)}
              onClick$={() => use(option.id)}
            >
              <span class="alternatives-palette__text">
                {word
                  ? option.text
                  : sentenceWordDiff(snapshot.text, option.text)
                      .filter((part) => part.kind !== "removed")
                      .map((part, i) =>
                        part.kind === "added" ? (
                          <em key={i}>{part.text}</em>
                        ) : (
                          <span key={i}>{part.text}</span>
                        ),
                      )}
              </span>
              <span class="alternatives-palette__meta">
                {(state.filter === "all" ||
                  (word && option.source === "model")) && (
                  <span class="alternatives-palette__tag">
                    {tagFor(option, word)}
                  </span>
                )}
                {!word && delta !== 0 && (
                  <span
                    class="alternatives-palette__delta"
                    title={`${Math.abs(delta)} ${Math.abs(delta) === 1 ? "word" : "words"} ${delta > 0 ? "longer" : "shorter"} than the original`}
                  >
                    {delta > 0 ? `+${delta}` : `−${-delta}`}
                  </span>
                )}
              </span>
            </div>
          );
        })}

        {empty && (
          <p class="alternatives-palette__empty" role="status">
            {emptyText}
          </p>
        )}
        {!empty && state.model === "loading" && (
          <p class="alternatives-palette__more" role="status">
            {state.rounds > 1
              ? "Finding more…"
              : word
                ? "Finding words that fit this sentence…"
                : "Finding more wordings…"}
          </p>
        )}
        {!empty &&
          (state.model === "done" || state.model === "error") &&
          state.rounds < MAX_MODEL_ROUNDS && (
            <button
              type="button"
              tabIndex={-1}
              class="alternatives-palette__more alternatives-palette__more--button"
              onClick$={() => {
                state.model = "done";
                return fetchModel(
                  snapshot,
                  state.filter === "all"
                    ? MODEL_LENSES_FOR[snapshot.scale]
                    : [state.filter],
                );
              }}
            >
              More
            </button>
          )}
      </div>

      {state.message && (
        <p class="alternatives-palette__notice" role="status">
          {state.message}
        </p>
      )}
      {state.model === "unavailable" && word && !empty && (
        <p class="alternatives-palette__notice">
          Word lists only. Connect a model in Settings, or sign in, for words
          chosen for this sentence.
        </p>
      )}

      <footer class="alternatives-palette__keys" aria-hidden="true">
        <span>
          <kbd>↑</kbd>
          <kbd>↓</kbd> or scroll the locked words
        </span>
        <span>
          <kbd>↵</kbd> use
        </span>
        <span>
          <kbd>←</kbd>
          <kbd>→</kbd> kind
        </span>
        <span>
          <kbd>Esc</kbd> keep
        </span>
        {activeIndex >= 0 && (
          <span class="alternatives-palette__position">
            {activeIndex + 1} of {options.length}
          </span>
        )}
      </footer>
    </div>
  );
});

toolUseResult.content:
/**
 * The Alternatives palette: a list of replacements for the locked span,
 * anchored beside it. The option under the pointer or the keyboard stands in
 * for the locked words in the manuscript until the writer uses one (Enter or
 * a click) or keeps the original (Escape).
 *
 * It opens on its own work: word lists and the model's wordings are fetched
 * as soon as a lock appears, and more are fetched as the writer reaches the
 * end of the list, up to {@link MAX_MODEL_ROUNDS} model rounds per lock.
 */
import {
  $,
  component$,
  useSignal,
  useStore,
  useVisibleTask$,
} from "@qwik.dev/core";
import { api } from "../../../convex/_generated/api";
import { useAuth } from "../../utils/auth-context";
import { useConvexClient } from "../../utils/convex-context";
import { loadAiSettingsFromIdb } from "../../utils/idb";
import {
  hasConfiguredAiProvider,
  runClientAlternatives,
} from "../../utils/ai-client";
import { normalizeApplicationError } from "../../utils/application-errors";
import {
  alternativesPrompt,
  LENS_LABELS,
  LENSES_FOR,
  lexiconQueries,
  MAX_MODEL_ROUNDS,
  mergeOptions,
  MODEL_LENSES_FOR,
  parseAlternatives,
  parseLexicon,
  parsePartsOfSpeech,
  partOfSpeechQuery,
  roundSize,
  wordDelta,
  type AlternativeLens,
  type AlternativeOption,
  type AlternativesRequest,
} from "../../utils/alternatives";
import { sentenceWordDiff } from "../../utils/sentence-bench";
import {
  ALTERNATIVES_EVENT,
  ALTERNATIVES_STEP_EVENT,
  alternativesController,
  alternativesSnapshot,
  type AlternativesSnapshot,
} from "./extensions/alternatives";

type Filter = "all" | AlternativeLens;
type Fetching = "idle" | "loading" | "done" | "unavailable" | "error";

interface PaletteState {
  snapshot: AlternativesSnapshot | null;
  options: AlternativeOption[];
  /** null: the original is selected. */
  activeId: string | null;
  filter: Filter;
  lexicon: Fetching;
  model: Fetching;
  rounds: number;
  message: string;
}

// ── Per-span memory ─────────────────────────────────────────────────────
// Reopening the same words in the same place shows what was already found
// and spends nothing. Browser-only, bounded.

interface CachedBrowse {
  options: AlternativeOption[];
  rounds: number;
  model: Fetching;
  lexicon: Fetching;
}
const browseCache = new Map<string, CachedBrowse>();
const cacheKey = (s: AlternativesSnapshot) =>
  JSON.stringify([s.scale, s.text, s.before.slice(-80), s.after.slice(0, 80)]);
const settled = (f: Fetching): Fetching =>
  f === "loading" || f === "error" ? "idle" : f;

function remember(state: PaletteState) {
  const s = state.snapshot;
  if (!s) return;
  const key = cacheKey(s);
  browseCache.delete(key);
  browseCache.set(key, {
    options: state.options.map((o) => ({ ...o })),
    rounds: state.rounds,
    model: settled(state.model),
    lexicon: settled(state.lexicon),
  });
  while (browseCache.size > 24)
    browseCache.delete(browseCache.keys().next().value!);
}

function addOptions(
  state: PaletteState,
  id: string,
  incoming: AlternativeOption[],
): number {
  if (state.snapshot?.id !== id || !incoming.length) return 0;
  const before = state.options.length;
  state.options = mergeOptions(state.options, incoming);
  return state.options.length - before;
}

// ── View helpers ────────────────────────────────────────────────────────

const LEXICON_TIMEOUT_MS = 4500;
const PALETTE_WIDTH = 368;
const TABS = (s: AlternativesSnapshot) =>
  ["all", ...LENSES_FOR[s.scale]] as Filter[];

function visibleOptions(state: PaletteState): AlternativeOption[] {
  const snapshot = state.snapshot;
  if (!snapshot) return [];
  if (state.filter !== "all")
    return state.options.filter((o) => o.lens === state.filter);
  if (snapshot.scale !== "word") return state.options;
  // Words read best grouped: synonyms, then antonyms, then slot fillers.
  const order = LENSES_FOR.word;
  return [...state.options].sort(
    (a, b) => order.indexOf(a.lens) - order.indexOf(b.lens),
  );
}

function placement(snapshot: AlternativesSnapshot) {
  const { anchor } = snapshot;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const width = Math.min(PALETTE_WIDTH, vw - 16);
  const center = (anchor.left + anchor.right) / 2;
  const left = Math.max(8, Math.min(vw - width - 8, center - width / 2));
  const below = vh - anchor.bottom;
  const above = anchor.top;
  const goBelow = below >= 280 || below >= above;
  const room = Math.max(180, (goBelow ? below : above) - 24);
  return {
    left,
    width,
    top: goBelow ? anchor.bottom + 12 : undefined,
    bottom: goBelow ? undefined : vh - anchor.top + 12,
    maxHeight: Math.min(460, room),
  };
}

function tagFor(option: AlternativeOption, word: boolean): string {
  // At word scale the model's synonyms are the ones chosen for this
  // sentence; the lexicon's are the dictionary's.
  if (word && option.source === "model" && option.lens === "synonym")
    return "fits here";
  return LENS_LABELS[option.lens].toLocaleLowerCase();
}

const optionDomId = (lock: string, id: string | null) =>
  `alternatives-option-${lock}-${id ? id.replace(/[^\w-]/g, "_") : "original"}`;

export const AlternativesPalette = component$(() => {
  const auth = useAuth();
  const client = useConvexClient();
  const root = useSignal<HTMLDivElement>();
  const list = useSignal<HTMLDivElement>();
  const state = useStore<PaletteState>({
    snapshot: null,
    options: [],
    activeId: null,
    filter: "all",
    lexicon: "idle",
    model: "idle",
    rounds: 0,
    message: "",
  });

  const fetchLexicon = $(async (snapshot: AlternativesSnapshot) => {
    if (snapshot.scale !== "word") return;
    const on = () => state.snapshot?.id === snapshot.id;
    state.lexicon = "loading";
    const abort = new AbortController();
    const timer = setTimeout(() => abort.abort(), LEXICON_TIMEOUT_MS);
    const get = async (url: string): Promise<unknown> => {
      const res = await fetch(url, { signal: abort.signal });
      if (!res.ok) throw new Error(`Word list ${res.status}`);
      return res.json();
    };
    try {
      const queries = lexiconQueries(snapshot);
      const [parts, ...bodies] = await Promise.allSettled([
        get(partOfSpeechQuery(snapshot.text)),
        ...queries.map((q) => get(q.url)),
      ]);
      if (!on()) return;
      const pos =
        parts.status === "fulfilled" ? parsePartsOfSpeech(parts.value) : [];
      let found: AlternativeOption[] = [];
      bodies.forEach((body, i) => {
        if (body.status !== "fulfilled") return;
        const query = queries[i]!;
        const parsed = parseLexicon(body.value, query, snapshot.text, pos);
        found = mergeOptions(
          found,
          parsed.slice(0, query.lens === "antonym" ? 10 : 18),
        );
      });
      addOptions(state, snapshot.id, found);
      state.lexicon = bodies.some((b) => b.status === "fulfilled")
        ? "done"
        : "error";
    } catch {
      if (on()) state.lexicon = "error";
    } finally {
      clearTimeout(timer);
      if (on()) remember(state);
    }
  });

  const fetchModel = $(
    async (snapshot: AlternativesSnapshot, lenses: AlternativeLens[]) => {
      if (state.model === "loading" || state.rounds >= MAX_MODEL_ROUNDS)
        return;
      const id = snapshot.id;
      const on = () => state.snapshot?.id === id;
      state.model = "loading";
      state.message = "";
      const request: AlternativesRequest = {
        text: snapshot.text,
        before: snapshot.before,
        after: snapshot.after,
        scale: snapshot.scale,
        lenses,
        count: roundSize(snapshot.scale, state.rounds),
        exclude: state.options.map((o) => o.text).slice(0, 40),
      };
      state.rounds++;
      let added = 0;
      try {
        const settings = await loadAiSettingsFromIdb();
        if (!on()) return;
        if (settings && hasConfiguredAiProvider(settings)) {
          const { system, prompt } = alternativesPrompt(request);
          const text = await runClientAlternatives(
            {
              system,
              prompt,
              scale: snapshot.scale,
              onText: (partial) => {
                added += addOptions(
                  state,
                  id,
                  parseAlternatives(partial, request, { partial: true }),
                );
              },
            },
            settings,
          );
          if (!on()) return;
          if (text === null) {
            state.model = "error";
            state.message =
              "Your model did not answer. Check its provider in Settings, or press More to try again.";
            return;
          }
          added += addOptions(state, id, parseAlternatives(text, request));
        } else if (
          auth.value.provider === "convex" &&
          auth.value.user &&
          client.value
        ) {
          const result = await client.value.action(api.alternatives.suggest, {
            text: request.text,
            before: request.before,
            after: request.after,
            scale: request.scale,
            lenses: request.lenses,
            count: request.count,
            exclude: request.exclude,
          });
          if (!on()) return;
          added += addOptions(state, id, result.options);
        } else {
          state.rounds--;
          state.model = "unavailable";
          return;
        }
        state.model = "done";
        if (!added && state.rounds > 1)
          state.message = "No new wordings this time.";
      } catch (error) {
        if (!on()) return;
        state.model = "error";
        state.message = normalizeApplicationError(error, {
          source: "provider",
          metadata: { feature: "alternatives" },
        }).message;
      } finally {
        if (on()) remember(state);
      }
    },
  );

  const setActive = $((id: string | null) => {
    const snapshot = state.snapshot;
    if (!snapshot) return;
    state.activeId = id;
    const option = id ? state.options.find((o) => o.id === id) : null;
    alternativesController()?.preview(option ? option.text : null);
    document
      .getElementById(optionDomId(snapshot.id, id))
      ?.scrollIntoView({ block: "nearest" });
  });

  const close = $((restoreSelection: boolean) => {
    alternativesController()?.preview(null);
    alternativesController()?.close({ restoreSelection });
  });

  const use = $((id: string | null) => {
    const option = id ? state.options.find((o) => o.id === id) : null;
    if (!option) {
      alternativesController()?.preview(null);
      alternativesController()?.close({ restoreSelection: true });
      return;
    }
    const result = alternativesController()?.apply(option.text) ?? {
      ok: false as const,
      message: "The manuscript is no longer open.",
    };
    if (!result.ok) state.message = result.message;
  });

  /** Near the end of the list, ask for more within the lock's budget. */
  const more = $(async (remaining: number) => {
    const snapshot = state.snapshot;
    if (!snapshot || remaining > 2) return;
    if (state.model !== "done" || state.rounds >= MAX_MODEL_ROUNDS) return;
    await fetchModel(
      snapshot,
      state.filter === "all"
        ? MODEL_LENSES_FOR[snapshot.scale]
        : [state.filter],
    );
  });

  const step = $(async (delta: number) => {
    const options = visibleOptions(state);
    const ids = [null, ...options.map((o) => o.id)];
    const at = Math.max(0, ids.indexOf(state.activeId));
    const next = Math.max(0, Math.min(ids.length - 1, at + delta));
    await setActive(ids[next] ?? null);
    await more(ids.length - 1 - next);
  });

  const choose = $(async (filter: Filter) => {
    const snapshot = state.snapshot;
    if (!snapshot) return;
    state.filter = filter;
    const shown = visibleOptions(state);
    if (state.activeId && !shown.some((o) => o.id === state.activeId))
      await setActive(null);
    // A kind with nothing in it yet gets a model round of its own.
    if (
      filter !== "all" &&
      !shown.length &&
      (state.model === "done" || state.model === "idle") &&
      MODEL_LENSES_FOR[snapshot.scale].includes(filter)
    )
      await fetchModel(snapshot, [filter]);
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    const begin = (snapshot: AlternativesSnapshot) => {
      const cached = browseCache.get(cacheKey(snapshot));
      state.snapshot = snapshot;
      state.options = cached?.options.map((o) => ({ ...o })) ?? [];
      state.rounds = cached?.rounds ?? 0;
      state.model = cached?.model ?? "idle";
      state.lexicon = cached?.lexicon ?? "idle";
      state.activeId = null;
      state.filter = "all";
      state.message = "";
      // Lists and the model start together: the word lists land first, the
      // model's wordings for this sentence stream in behind them.
      if (state.lexicon === "idle") void fetchLexicon(snapshot);
      if (state.rounds === 0) void fetchModel(snapshot, MODEL_LENSES_FOR[snapshot.scale]);
      requestAnimationFrame(() =>
        list.value?.focus({ preventScroll: true }),
      );
    };
    const follow = (event: Event) => {
      const next = (event as CustomEvent<AlternativesSnapshot | null>).detail;
      if (!next) {
        remember(state);
        state.snapshot = null;
        state.options = [];
        state.activeId = null;
        return;
      }
      // Same lock, new position: the page scrolled.
      if (state.snapshot?.id === next.id) state.snapshot = next;
      else begin(next);
    };
    const onStep = (event: Event) => {
      if (state.snapshot) void step((event as CustomEvent<number>).detail);
    };
    // Native, so arrow keys and Enter are stopped before the list scrolls or
    // the editor's own shortcuts see them.
    const onKey = (event: KeyboardEvent) => {
      const snapshot = state.snapshot;
      const target = event.target as HTMLElement | null;
      if (!snapshot || !target?.closest?.(".alternatives-palette")) return;
      if (event.metaKey || event.ctrlKey || event.altKey) return;
      const key = event.key;
      const stop = () => {
        event.preventDefault();
        event.stopPropagation();
      };
      const onTab = target.getAttribute("role") === "tab";
      if (key === "Escape") {
        stop();
        void close(true);
      } else if (key === "ArrowDown") {
        stop();
        void step(1);
      } else if (key === "ArrowUp") {
        stop();
        void step(-1);
      } else if (key === "PageDown") {
        stop();
        void step(6);
      } else if (key === "PageUp") {
        stop();
        void step(-6);
      } else if (key === "Home" && !onTab) {
        stop();
        void setActive(null);
      } else if (key === "End" && !onTab) {
        stop();
        void step(state.options.length + 1);
      } else if (key === "ArrowRight" || key === "ArrowLeft") {
        stop();
        const tabs = TABS(snapshot);
        const at = tabs.indexOf(state.filter);
        const delta = key === "ArrowRight" ? 1 : -1;
        void choose(tabs[(at + delta + tabs.length) % tabs.length]!);
      } else if (key === "Enter" && !target.closest("button")) {
        stop();
        void use(state.activeId);
      }
    };
    const onPointer = (event: PointerEvent) => {
      if (!state.snapshot) return;
      const target = event.target as HTMLElement | null;
      // Clicks in the manuscript are the extension's to judge.
      if (
        target?.closest?.(".alternatives-palette") ||
        target?.closest?.(".ProseMirror")
      )
        return;
      void close(false);
    };
    window.addEventListener(ALTERNATIVES_EVENT, follow);
    window.addEventListener(ALTERNATIVES_STEP_EVENT, onStep);
    document.addEventListener("keydown", onKey, true);
    document.addEventListener("pointerdown", onPointer, true);
    const open = alternativesSnapshot();
    if (open) begin(open);
    cleanup(() => {
      window.removeEventListener(ALTERNATIVES_EVENT, follow);
      window.removeEventListener(ALTERNATIVES_STEP_EVENT, onStep);
      document.removeEventListener("keydown", onKey, true);
      document.removeEventListener("pointerdown", onPointer, true);
    });
  });

  const snapshot = state.snapshot;
  if (!snapshot) return null;

  const word = snapshot.scale === "word";
  const options = visibleOptions(state);
  const counts = new Map<AlternativeLens, number>();
  for (const o of state.options)
    counts.set(o.lens, (counts.get(o.lens) ?? 0) + 1);
  const box = placement(snapshot);
  const loading = state.lexicon === "loading" || state.model === "loading";
  const activeIndex = state.activeId
    ? options.findIndex((o) => o.id === state.activeId)
    : -1;
  const empty = !options.length;
  const emptyText =
    state.model === "unavailable" && !word
      ? "Rewordings need a model. Connect one in Settings, or sign in to use Twyne's."
      : loading
        ? "Finding alternatives…"
        : state.filter !== "all"
          ? `No ${LENS_LABELS[state.filter].toLocaleLowerCase()} for this ${snapshot.scale} yet.`
          : "Nothing fits this slot yet.";

  return (
    <div
      ref={root}
      class={["alternatives-palette", `alternatives-palette--${snapshot.scale}`]}
      style={{
        left: `${box.left}px`,
        width: `${box.width}px`,
        top: box.top === undefined ? undefined : `${box.top}px`,
        bottom: box.bottom === undefined ? undefined : `${box.bottom}px`,
        maxHeight: `${box.maxHeight}px`,
      }}
      role="dialog"
      aria-label={`Alternatives for “${snapshot.text.slice(0, 60)}”`}
      data-alternatives-palette={snapshot.id}
    >
      <header class="alternatives-palette__head">
        <p class="alternatives-palette__kicker">
          Alternatives
          <span class="alternatives-palette__budget">
            {word
              ? "for this word"
              : `about ${snapshot.words} words, like the original`}
          </span>
        </p>
        <button
          type="button"
          class="alternatives-palette__close"
          aria-label="Keep the original and close"
          title="Keep the original (Esc)"
          onClick$={() => close(true)}
        >
          ×
        </button>
