  background-color: color-mix(in srgb, var(--color-cobalt) 11%, transparent);
  box-shadow: inset 0 -1px 0
    color-mix(in srgb, var(--color-cobalt) 70%, transparent);
  cursor: ns-resize;
}
.twyne-alt-lock--previewing {
  display: none;
}
.twyne-alt-ghost {
  background-color: color-mix(in srgb, var(--color-cobalt) 17%, transparent);
  box-shadow: inset 0 -2px 0 var(--color-cobalt);
}
.alternatives-palette {
  position: fixed;
  z-index: var(--z-dropdown);
  display: flex;
  flex-direction: column;
  min-height: 0;
  border: 1px solid color-mix(in srgb, var(--color-ink-muted) 52%, transparent);
  background: color-mix(in srgb, var(--color-paper) 95%, transparent);
  box-shadow: 0 0.65rem 1.8rem rgba(32, 25, 16, 0.22);
  backdrop-filter: blur(14px) saturate(0.9);
  color: var(--color-ink);
}
.alternatives-palette__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.45rem 0.4rem 0.35rem 0.7rem;
}
.alternatives-palette__kicker {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.15rem 0.5rem;
  color: var(--color-ink);
  font-family: var(--font-typewriter);
  font-size: 0.62rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.alternatives-palette__budget {
  color: var(--color-ink-muted);
  letter-spacing: 0.04em;
  text-transform: none;
}
.alternatives-palette__close {
  padding: 0.15rem 0.4rem;
  color: var(--color-ink-muted);
  font-size: 0.9rem;
  line-height: 1;
}
.alternatives-palette__close:hover {
  color: var(--color-vermilion);
}
.alternatives-palette__lenses {
  display: flex;
  gap: 0.15rem;
  padding: 0 0.45rem 0.4rem;
  overflow-x: auto;
  scrollbar-width: none;
  border-bottom: 1px solid var(--color-paper-3);
}
.alternatives-palette__lenses > button {
  display: inline-flex;
  flex-shrink: 0;
  align-items: baseline;
  gap: 0.3rem;
  padding: 0.22rem 0.45rem;
  border: 1px solid transparent;
  color: var(--color-ink-light);
  font-family: var(--font-typewriter);
  font-size: 0.64rem;
  white-space: nowrap;
}
.alternatives-palette__lenses > button:hover {
  color: var(--color-cobalt);
}
.alternatives-palette__lenses > button.is-on {
  border-color: color-mix(in srgb, var(--color-cobalt) 45%, transparent);
  background: color-mix(in srgb, var(--color-cobalt) 8%, transparent);
  color: var(--color-ink);
}
.alternatives-palette__count {
  color: var(--color-ink-muted);
  font-size: 0.58rem;
}
.alternatives-palette__list {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  outline: none;
  padding: 0.2rem 0;
}
.alternatives-palette__list:focus-visible {
  box-shadow: inset 0 0 0 2px
    color-mix(in srgb, var(--color-cobalt) 45%, transparent);
}
.alternatives-palette__option {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.36rem 0.7rem;
  border-left: 2px solid transparent;
  cursor: pointer;
}
.alternatives-palette__option.is-active {
  border-left-color: var(--color-cobalt);
  background: color-mix(in srgb, var(--color-cobalt) 9%, transparent);
}
.alternatives-palette__text {
  min-width: 0;
  color: var(--color-ink);
  font-family: var(--font-serif);
  font-size: 0.95rem;
  line-height: 1.45;
  overflow-wrap: anywhere;
}
.alternatives-palette--word .alternatives-palette__text {
  font-size: 1.02rem;
}
.alternatives-palette__text em {
  font-style: normal;
  box-shadow: inset 0 -1px 0
    color-mix(in srgb, var(--color-cobalt) 65%, transparent);
}
.alternatives-palette__option--original .alternatives-palette__text {
  color: var(--color-ink-light);
}
.alternatives-palette__meta {
  display: inline-flex;
  flex-shrink: 0;
  align-items: baseline;
  gap: 0.4rem;
}
.alternatives-palette__tag,
.alternatives-palette__delta {
  color: var(--color-ink-muted);
  font-family: var(--font-typewriter);
  font-size: 0.58rem;
  letter-spacing: 0.03em;
  white-space: nowrap;
}
.alternatives-palette__delta {
  color: var(--color-ink-light);
}
.alternatives-palette__empty,
.alternatives-palette__more {
  display: block;
  width: 100%;
  padding: 0.55rem 0.7rem;
  color: var(--color-ink-muted);
  font-family: var(--font-typewriter);
  font-size: 0.64rem;
  text-align: left;
}
.alternatives-palette__more--button:hover {
  color: var(--color-cobalt);
}
.alternatives-palette__notice {
  padding: 0.4rem 0.7rem;
  border-top: 1px solid var(--color-paper-3);
  color: var(--color-ink-light);
  font-family: var(--font-typewriter);
  font-size: 0.62rem;
  line-height: 1.45;
}
.alternatives-palette__keys {
  display: flex;
  flex-wrap: wrap;
  gap: 0.2rem 0.7rem;
  padding: 0.4rem 0.7rem;
  border-top: 1px solid var(--color-paper-3);
  color: var(--color-ink-muted);
  font-family: var(--font-typewriter);
  font-size: 0.58rem;
}
.alternatives-palette__keys kbd {
  margin-right: 0.12rem;
  font-family: inherit;
  color: var(--color-ink-light);
}
.alternatives-palette__position {
  margin-left: auto;
}
@media (pointer: coarse) {
  .alternatives-palette__keys {
    display: none;
  }
  .alternatives-palette__option {
    padding-block: 0.55rem;
  }
}
@media print {
  .alternatives-palette,
  .twyne-alt-ghost {
    display: none !important;
  }
  .twyne-alt-lock,
  .twyne-alt-lock--previewing {
    display: inline !important;
    background: none !important;
    box-shadow: none !important;
  }
}

