import { chromium } from "/home/diogenes/Projects/apps/twyne/node_modules/playwright/index.mjs";

const BASE = "http://127.0.0.1:5174";
const OUT = "/tmp/claude-1000/-home-diogenes-Projects-apps-twyne/e8f36531-c27d-4be0-9028-f9a9a68a26ed/scratchpad";
const HTML =
  "<p>It was a happy day for the whole village, and nobody wanted it to end.</p>" +
  "<p>The old house stood alone at the end of the lane, its shutters closed against the wind.</p>";

const sse = (text) => {
  const chunk = (delta, finish = null) =>
    `data: ${JSON.stringify({ id: "s", object: "chat.completion.chunk", created: 0, model: "stub-model", choices: [{ index: 0, delta, finish_reason: finish }] })}\n\n`;
  const parts = text.match(/[\s\S]{1,40}/g) ?? [];
  return (
    chunk({ role: "assistant", content: "" }) +
    parts.map((p) => chunk({ content: p })).join("") +
    chunk({}, "stop") +
    `data: ${JSON.stringify({ id: "s", object: "chat.completion.chunk", created: 0, model: "stub-model", choices: [], usage: { prompt_tokens: 10, completion_tokens: 10, total_tokens: 20 } })}\n\n` +
    "data: [DONE]\n\n"
  );
};

const WORD = [
  { lens: "synonym", text: "joyful" },
  { lens: "synonym", text: "glad" },
  { lens: "synonym", text: "sunlit" },
  { lens: "antonym", text: "bleak" },
  { lens: "slot", text: "busy" },
];
const PHRASE = [
  { lens: "rephrase", text: "The empty house" },
  { lens: "rephrase", text: "The aging farmhouse" },
  { lens: "plainer", text: "The old home" },
  { lens: "sharper", text: "The gray clapboard house" },
  { lens: "formal", text: "The ancestral residence" },
  { lens: "looser", text: "That creaky old place" },
  { lens: "opposite", text: "The new house" },
  { lens: "rephrase", text: "An old house that nobody had lived in for years" },
];

const requests = [];
const log = (...a) => console.log(...a);

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 860 } });
page.on("pageerror", (e) => log("PAGEERROR", e.message));
page.on("console", (m) => {
  if (m.type() === "error" && !/favicon|posthog|convex|Failed to load resource/i.test(m.text()))
    log("CONSOLE", m.text().slice(0, 300));
});
await page.route(/\/api\/auth\//, (r) => r.fulfill({ contentType: "application/json", body: "null" }));
await page.route("**/__alt-seed", (r) => r.fulfill({ contentType: "text/html", body: "<!doctype html><title>seed</title>" }));
await page.route("**/stub-llm/v1/**", async (route) => {
  const body = route.request().postDataJSON();
  const prompt = JSON.stringify(body);
  requests.push(prompt);
  const lines = prompt.includes('SPAN: \\"happy\\"') ? WORD : PHRASE;
  await route.fulfill({
    status: 200,
    headers: { "content-type": "text/event-stream", "access-control-allow-origin": "*" },
    body: sse(lines.map((l) => JSON.stringify(l)).join("\n")),
  });
});

await page.goto(`${BASE}/__alt-seed`);
await page.evaluate(async (html) => {
  const db = await import(/* @vite-ignore */ "/src/utils/idb.ts");
  const now = Date.now(), id = "alt-fixture";
  await db.saveFoliosToIdb([{ id, name: "Alternatives check", type: "draft", createdAt: now, updatedAt: now }]);
  await db.saveFolioContentToIdb(id, html);
  await db.saveActiveFolioIdToIdb(id);
  await db.saveMetaToIdb("live-review-enabled", false);
  await db.saveMetaToIdb("signin-toast-dismissed", true);
  await db.saveAiSettingsToIdb({
    advancedMode: true,
    providers: [{ id: "stub", name: "Stub", type: "openai-compatible", apiKey: "x", baseUrl: `${location.origin}/stub-llm/v1`, defaultModel: "stub-model", apiMode: "chat" }],
    defaultProviderId: "stub",
    perFeature: {},
    showProviderTags: false,
  });
  localStorage.setItem("living-desk-open", "false");
  localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
}, HTML);
await page.goto(`${BASE}/editor/`);
const pm = page.locator("#twyne-editor-mount .ProseMirror");
await pm.getByText("It was a happy day").waitFor({ timeout: 90_000 });
await page.waitForTimeout(1500);

// ── 1. Single word via the selection toolbar ──────────────────────────
const word = pm.locator("p").first();
const box = await word.boundingBox();
// Double-click "happy": find its rect via a Range.
const happy = await page.evaluate(() => {
  const p = document.querySelector("#twyne-editor-mount .ProseMirror p");
  const walker = document.createTreeWalker(p, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    const i = node.data.indexOf("happy");
    if (i >= 0) {
      const r = document.createRange();
      r.setStart(node, i);
      r.setEnd(node, i + 5);
      const b = r.getBoundingClientRect();
      return { x: b.left + b.width / 2, y: b.top + b.height / 2 };
    }
  }
  return null;
});
await page.mouse.dblclick(happy.x, happy.y);
const toolbarButton = page.locator(".selection-actions button", { hasText: "Alternatives" });
await toolbarButton.waitFor({ timeout: 10_000 });
log("toolbar title:", await toolbarButton.getAttribute("title"));
await toolbarButton.click();
const palette = page.locator(".alternatives-palette[data-alternatives-palette]");
await palette.waitFor({ timeout: 10_000 });
await page.waitForFunction(() => document.querySelectorAll(".alternatives-palette__option").length > 6, null, { timeout: 15_000 }).catch(() => {});
await page.waitForTimeout(800);
const wordOptions = await page.locator(".alternatives-palette__option").evaluateAll((els) =>
  els.map((e) => e.innerText.replace(/\s+/g, " ").trim()),
);
log("word options:", wordOptions.length, JSON.stringify(wordOptions.slice(0, 40)));
log("tabs:", JSON.stringify(await page.locator(".alternatives-palette__lenses button").allInnerTexts()));
log("focused in palette:", await page.evaluate(() => !!document.activeElement?.closest(".alternatives-palette")));
await page.screenshot({ path: `${OUT}/alt-word.png` });

await page.keyboard.press("ArrowDown");
await page.keyboard.press("ArrowDown");
await page.waitForTimeout(200);
log("ghost after 2x down:", await page.locator(".twyne-alt-ghost").innerText().catch(() => "(none)"));
log("doc unchanged:", (await word.innerText()).includes("happy day"));
await page.screenshot({ path: `${OUT}/alt-word-preview.png` });

// Wheel over the locked words steps too.
const ghostBox = await page.locator(".twyne-alt-ghost").boundingBox();
await page.mouse.move(ghostBox.x + ghostBox.width / 2, ghostBox.y + ghostBox.height / 2);
await page.mouse.wheel(0, 120);
await page.waitForTimeout(250);
log("ghost after wheel:", await page.locator(".twyne-alt-ghost").innerText().catch(() => "(none)"));
log("position:", await page.locator(".alternatives-palette__position").innerText().catch(() => "-"));

// Antonyms tab via ArrowRight.
await page.keyboard.press("ArrowRight");
await page.keyboard.press("ArrowRight");
await page.waitForTimeout(200);
log("tab selected:", await page.locator('.alternatives-palette__lenses [aria-selected="true"]').innerText());
log("antonym options:", JSON.stringify(await page.locator(".alternatives-palette__option").allInnerTexts()));
await page.keyboard.press("ArrowDown");
const chosen = await page.locator(".twyne-alt-ghost").innerText();
await page.keyboard.press("Enter");
await page.waitForTimeout(300);
log("chosen:", chosen, "| paragraph now:", (await word.innerText()).slice(0, 40));
log("palette gone:", (await palette.count()) === 0);
await page.keyboard.press("Control+z");
await page.waitForTimeout(300);
log("after undo:", (await word.innerText()).slice(0, 40));

// ── 2. Phrase via Shift+F7 on a selection ─────────────────────────────
await page.evaluate(() => {
  const p = document.querySelectorAll("#twyne-editor-mount .ProseMirror p")[1];
  const node = p.firstChild;
  const r = document.createRange();
  r.setStart(node, 0);
  r.setEnd(node, "The old house".length);
  const sel = getSelection();
  sel.removeAllRanges();
  sel.addRange(r);
});
await page.waitForTimeout(300);
await page.keyboard.press("Shift+F7");
await palette.waitFor({ timeout: 10_000 });
await page.waitForFunction(() => document.querySelectorAll(".alternatives-palette__option").length > 3, null, { timeout: 15_000 }).catch(() => {});
await page.waitForTimeout(500);
log("phrase options:", JSON.stringify(await page.locator(".alternatives-palette__option").evaluateAll((els) => els.map((e) => e.innerText.replace(/\s+/g, " ").trim()))));
log("phrase head:", await page.locator(".alternatives-palette__head").innerText());
log("phrase tabs:", JSON.stringify(await page.locator(".alternatives-palette__lenses button").allInnerTexts()));
