102	function addOptions(
103	  state: PaletteState,
104	  id: string,
105	  incoming: AlternativeOption[],
106	): number {
107	  if (state.snapshot?.id !== id || !incoming.length) return 0;
108	  const before = state.options.length;
109	  state.options = mergeOptions(state.options, incoming);
110	  return state.options.length - before;
111	}
112	
113	// ── View helpers ────────────────────────────────────────────────────────
114	
115	const LEXICON_TIMEOUT_MS = 4500;
116	const PALETTE_WIDTH = 368;
117	const TABS = (s: AlternativesSnapshot) =>
118	  ["all", ...LENSES_FOR[s.scale]] as Filter[];
119	
120	function visibleOptions(state: PaletteState): AlternativeOption[] {
121	  const snapshot = state.snapshot;
122	  if (!snapshot) return [];
123	  if (state.filter !== "all")
124	    return state.options.filter((o) => o.lens === state.filter);
125	  if (snapshot.scale !== "word") return state.options;
126	  // Words read best grouped: synonyms, then antonyms, then slot fillers.
127	  const order = LENSES_FOR.word;
128	  return [...state.options].sort(
129	    (a, b) => order.indexOf(a.lens) - order.indexOf(b.lens),
130	  );
131	}
132	
133	function placement({ anchor }: Pick<AlternativesSnapshot, "anchor">) {
134	  const vw = window.innerWidth;
135	  const vh = window.innerHeight;
136	  const width = Math.min(PALETTE_WIDTH, vw - 16);
137	  const center = (anchor.left + anchor.right) / 2;
138	  const left = Math.max(8, Math.min(vw - width - 8, center - width / 2));
139	  const below = vh - anchor.bottom;
140	  const above = anchor.top;
141	  const goBelow = below >= 280 || below >= above;
142	  const room = Math.max(180, (goBelow ? below : above) - 24);
143	  return {
144	    left,
145	    width,
146	    top: goBelow ? anchor.bottom + 12 : undefined,
147	    bottom: goBelow ? undefined : vh - anchor.top + 12,
148	    maxHeight: Math.min(460, room),
149	  };
150	}
151	
152	function tagFor(option: AlternativeOption, word: boolean): string {
153	  // At word scale the model's synonyms are the ones chosen for this
154	  // sentence; the lexicon's are the dictionary's.
155	  if (word && option.source === "model" && option.lens === "synonym")
156	    return "fits here";
157	  return LENS_LABELS[option.lens].toLocaleLowerCase();
158	}
159	
160	const optionDomId = (lock: string, id: string | null) =>
161	  `alternatives-option-${lock}-${id ? id.replace(/[^\w-]/g, "_") : "original"}`;
162	
163	export const AlternativesPalette = component$(() => {
164	  const auth = useAuth();
165	  const client = useConvexClient();
166	  const root = useSignal<HTMLDivElement>();
167	  const list = useSignal<HTMLDivElement>();
168	  const refusal = useSignal<AlternativesRefusal | null>(null);
169	  const state = useStore<PaletteState>({
170	    snapshot: null,
171	    options: [],
172	    activeId: null,
173	    filter: "all",
174	    lexicon: "idle",
175	    model: "idle",
176	    rounds: 0,
177	    message: "",
178	  });
179	
180	  const fetchLexicon = $(async (snapshot: AlternativesSnapshot) => {
181	    if (snapshot.scale !== "word") return;
182	    const on = () => state.snapshot?.id === snapshot.id;
183	    state.lexicon = "loading";
184	    const abort = new AbortController();
185	    const timer = setTimeout(() => abort.abort(), LEXICON_TIMEOUT_MS);
186	    const get = async (url: string): Promise<unknown> => {
187	      const res = await fetch(url, { signal: abort.signal });
188	      if (!res.ok) throw new Error(`Word list ${res.status}`);
189	      return res.json();
190	    };
191	    try {
192	      const queries = lexiconQueries(snapshot);
193	      const [parts, ...bodies] = await Promise.allSettled([
194	        get(partOfSpeechQuery(snapshot.text)),
195	        ...queries.map((q) => get(q.url)),
196	      ]);
197	      if (!on()) return;
198	      const pos =
199	        parts.status === "fulfilled" ? parsePartsOfSpeech(parts.value) : [];
200	      let found: AlternativeOption[] = [];
201	      bodies.forEach((body, i) => {
202	        if (body.status !== "fulfilled") return;
203	        const query = queries[i]!;
204	        const parsed = parseLexicon(body.value, query, snapshot.text, pos);
205	        found = mergeOptions(
206	          found,
207	          parsed.slice(0, query.lens === "antonym" ? 10 : 18),
208	        );
209	      });
210	      addOptions(state, snapshot.id, found);
211	      state.lexicon = bodies.some((b) => b.status === "fulfilled")
212	        ? "done"
213	        : "error";
214	    } catch {
215	      if (on()) state.lexicon = "error";
216	    } finally {
217	      clearTimeout(timer);
218	      if (on()) remember(state);
219	    }
220	  });
221	
222	  const fetchModel = $(
223	    async (snapshot: AlternativesSnapshot, lenses: AlternativeLens[]) => {
224	      if (state.model === "loading" || state.rounds >= MAX_MODEL_ROUNDS) return;
225	      const id = snapshot.id;
226	      const on = () => state.snapshot?.id === id;
227	      state.model = "loading";
228	      state.message = "";
229	      const request: AlternativesRequest = {
230	        text: snapshot.text,
231	        before: snapshot.before,
232	        after: snapshot.after,
233	        scale: snapshot.scale,
234	        lenses,
235	        count: roundSize(snapshot.scale, state.rounds),
236	        exclude: state.options.map((o) => o.text).slice(0, 40),
237	      };
238	      state.rounds++;
239	      let added = 0;
240	      try {
241	        const settings = await loadAiSettingsFromIdb();
242	        if (!on()) return;
243	        if (settings && hasConfiguredAiProvider(settings)) {
244	          const { system, prompt } = alternativesPrompt(request);
245	          const text = await runClientAlternatives(
246	            {
247	              system,
248	              prompt,
249	              scale: snapshot.scale,
250	              onText: (partial) => {
251	                added += addOptions(
252	                  state,
253	                  id,
254	                  parseAlternatives(partial, request, { partial: true }),
255	                );
256	              },
257	            },
258	            settings,
259	          );
260	          if (!on()) return;
261	          if (text === null) {
262	            state.model = "error";
263	            state.message =
264	              "Your model did not answer. Check its provider in Settings, or press More to try again.";
265	            return;
266	          }
267	          added += addOptions(state, id, parseAlternatives(text, request));
268	        } else if (
269	          auth.value.provider === "convex" &&
270	          auth.value.user &&
271	          client.value
272	        ) {
273	          const result = await client.value.action(api.alternatives.suggest, {
274	            text: request.text,
275	            before: request.before,
276	            after: request.after,
277	            scale: request.scale,
278	            lenses: request.lenses,
279	            count: request.count,
280	            exclude: request.exclude,
281	          });
282	          if (!on()) return;
283	          added += addOptions(state, id, result.options);
284	        } else {
285	          state.rounds--;
286	          state.model = "unavailable";
287	          return;
288	        }
289	        state.model = "done";
290	        if (!added && state.rounds > 1)
291	          state.message = "No new wordings this time.";
292	      } catch (error) {
293	        if (!on()) return;
294	        state.model = "error";
295	        state.message = normalizeApplicationError(error, {
296	          source: "provider",
297	          metadata: { feature: "alternatives" },
298	        }).message;
299	      } finally {
300	        if (on()) remember(state);
301	      }
302	    },
303	  );
304	
305	  const setActive = $((id: string | null) => {
306	    const snapshot = state.snapshot;
307	    if (!snapshot) return;
308	    state.activeId = id;
309	    const option = id ? state.options.find((o) => o.id === id) : null;
310	    alternativesController()?.preview(option ? option.text : null);
311	    document
312	      .getElementById(optionDomId(snapshot.id, id))
313	      ?.scrollIntoView({ block: "nearest" });
314	  });
315	
316	  const close = $((restoreSelection: boolean) => {
317	    alternativesController()?.preview(null);
318	    alternativesController()?.close({ restoreSelection });
319	  });
320	
321	  const use = $((id: string | null) => {
322	    const option = id ? state.options.find((o) => o.id === id) : null;
323	    if (!option) {
324	      alternativesController()?.preview(null);
325	      alternativesController()?.close({ restoreSelection: true });
326	      return;
327	    }
328	    const result = alternativesController()?.apply(option.text) ?? {
329	      ok: false as const,
330	      message: "The manuscript is no longer open.",
331	    };
332	    if (!result.ok) state.message = result.message;
333	  });
334	
335	  /** Near the end of the list, ask for more within the lock's budget. */
336	  const more = $(async (remaining: number) => {
337	    const snapshot = state.snapshot;
338	    if (!snapshot || remaining > 2) return;
339	    if (state.model !== "done" || state.rounds >= MAX_MODEL_ROUNDS) return;
340	    await fetchModel(
341	      snapshot,
342	      state.filter === "all"
343	        ? MODEL_LENSES_FOR[snapshot.scale]
344	        : [state.filter],
345	    );
346	  });
347	
348	  const step = $(async (delta: number) => {
349	    const options = visibleOptions(state);
350	    const ids = [null, ...options.map((o) => o.id)];
351	    const at = Math.max(0, ids.indexOf(state.activeId));
352	    const next = Math.max(0, Math.min(ids.length - 1, at + delta));
353	    await setActive(ids[next] ?? null);
354	    await more(ids.length - 1 - next);
355	  });
356	
357	  const choose = $(async (filter: Filter) => {
358	    const snapshot = state.snapshot;
359	    if (!snapshot) return;
360	    state.filter = filter;
361	    const shown = visibleOptions(state);
362	    if (state.activeId && !shown.some((o) => o.id === state.activeId))
363	      await setActive(null);
364	    // A kind with nothing in it yet gets a model round of its own.
365	    if (
366	      filter !== "all" &&
367	      !shown.length &&
368	      (state.model === "done" || state.model === "idle") &&
