const onKey = (event: KeyboardEvent) => {
  const snapshot = state.snapshot;
  const target = event.target as HTMLElement | null;
  if (!snapshot || !target?.closest?.(".alternatives-palette")) return;
  if (event.metaKey || event.ctrlKey || event.altKey) return;
  const key = event.key;
  const stop = () => {
    event.preventDefault();
    event.stopPropagation();
  };
  const onTab = target.getAttribute("role") === "tab";
  if (key === "Escape") {
    stop();
    void close(true);
  } else if (key === "ArrowDown") {
    stop();
    void step(1);
  } else if (key === "ArrowUp") {
    stop();
    void step(-1);
  } else if (key === "PageDown") {
    stop();
    void step(6);
  } else if (key === "PageUp") {
    stop();
    void step(-6);
  } else if (key === "Home" && !onTab) {
    stop();
    void setActive(null);
  } else if (key === "End" && !onTab) {
    stop();
    void step(state.options.length + 1);
  } else if (key === "ArrowRight" || key === "ArrowLeft") {
    stop();
    const tabs = TABS(snapshot);
    const at = tabs.indexOf(state.filter);
    const delta = key === "ArrowRight" ? 1 : -1;
    void choose(tabs[(at + delta + tabs.length) % tabs.length]!);
  } else if (key === "Enter" && !target.closest("button")) {
    stop();
    void use(state.activeId);
  }
};
let refusalTimer: ReturnType<typeof setTimeout> | undefined;

