await page.locator("#margin .steer input").fill("lonelier"); await page.keyboard.press("Enter"); await page.waitForTimeout(100);
console.log("steer:", await st("margin"), "| span:", await page.locator("#rail-span").innerText());
await page.screenshot({ path: `${OUT}/ui-margin.png`, fullPage: true });

// Interlinear
await tab("Interlinear"); await focus("inter");
await page.keyboard.press("ArrowDown");
console.log("inter span preview:", await page.locator("#int-span").innerText());
await page.screenshot({ path: `${OUT}/ui-inter.png`, fullPage: true });
await page.keyboard.press("m"); console.log("inter m:", await st("inter"));
await page.keyboard.press("3"); console.log("inter 3:", await st("inter"));

// Tone map
await tab("Tone map"); await focus("map");
for (let k = 0; k < 6; k++) await page.keyboard.press("ArrowUp");
for (let k = 0; k < 6; k++) await page.keyboard.press("ArrowRight");
console.log("map:", await st("map"));
