await page.mouse.click(mb.x + mb.width * 0.55, mb.y + mb.height * 0.85);
console.log("map click:", await st("map"));
await page.screenshot({ path: `${OUT}/ui-map.png`, fullPage: true });

// Tumblers
await tab("Tumblers"); await focus("tumblers");
await page.keyboard.press("ArrowDown"); await page.keyboard.press("ArrowRight"); await page.keyboard.press("ArrowDown"); await page.keyboard.press("ArrowRight"); await page.keyboard.press("ArrowRight"); await page.keyboard.press("ArrowRight"); await page.keyboard.press("ArrowDown"); await page.keyboard.press("ArrowDown"); await page.keyboard.press("ArrowDown");
console.log("tumblers:", await page.locator("#tum-line").innerText().then((t) => t.replace(/\s+/g, " ")), "|", await st("tumblers"));
await page.screenshot({ path: `${OUT}/ui-tumblers.png`, fullPage: true });
await page.keyboard.press("Enter"); console.log("tum enter:", await st("tumblers"));
await page.locator("#tumblers .whole button").first().click(); await page.keyboard.press("Enter"); console.log("tum whole:", await st("tumblers"));
await page.keyboard.press("Escape"); console.log("tum esc:", (await page.locator("#tum-line").innerText()).replace(/\s+/g, " "));

// Proof sheet
await tab("Proof sheet"); await focus("sheet");
await page.keyboard.press("ArrowRight"); await page.keyboard.press("ArrowDown");
console.log("sheet:", await st("sheet"));
await page.screenshot({ path: `${OUT}/ui-sheet.png`, fullPage: true });
await page.keyboard.press("Enter"); console.log("sheet enter:", await st("sheet"));

// Phone width
await page.setViewportSize({ width: 390, height: 900 });
await tab("Margin"); await page.waitForTimeout(150);
const overflow = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth);
console.log("phone horizontal overflow:", overflow);
await page.screenshot({ path: `${OUT}/ui-phone-margin.png`, fullPage: true });
console.log("height at 728:", await page.setViewportSize({ width: 728, height: 1000 }).then(() => page.evaluate(() => document.documentElement.scrollHeight)));
console.log("errors:", errors);
await browser.close();
EOF
timeout 120 env -u LD_LIBRARY_PATH node ui-check.mjs 2>&1 | tail -40

