content.content:
1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Alternatives interfaces</title>
7	<link rel="preconnect" href="https://fonts.googleapis.com">
8	<link href="https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400;0,500;1,400&family=Special+Elite&display=swap" rel="stylesheet">
9	<style>
10	:root{
11	  --paper:#f4ecd8;--paper-soft:#faf3df;--rule:#ddd0b1;
12	  --ink:#1f1b16;--ink-2:#4a3f33;--ink-3:#8a7e6c;--cobalt:#2c4a7c;--verm:#c1272d;
13	  --serif:"Lora",Georgia,"Times New Roman",serif;
14	  --type:"Special Elite","Courier New",monospace;
15	}
16	.ink-dark{--paper:#191714;--paper-soft:#252119;--rule:#3b3630;--ink:#ece4d4;--ink-2:#c4bbab;--ink-3:#8e8577;--cobalt:#7396c9;--verm:#e2686c}
17	*{box-sizing:border-box}
18	.wrap{display:grid;gap:14px}
19	.intro{margin:0;color:var(--muted-foreground);font-size:13px;line-height:1.5}
20	.tabs{display:flex;gap:2px;overflow-x:auto;scrollbar-width:none;border-bottom:1px solid var(--border)}
21	.tabs button{flex:0 0 auto;font:inherit;font-size:13px;padding:8px 10px;border:0;background:none;color:var(--muted-foreground);border-bottom:2px solid transparent;margin-bottom:-1px;cursor:pointer}
22	.tabs button[aria-selected=true]{color:var(--foreground);border-bottom-color:var(--primary)}
23	.tabs button:focus-visible{outline:2px solid var(--ring);outline-offset:-2px}
24	.concept{display:grid;gap:10px}
25	.concept[hidden]{display:none}
26	.c-head h2{margin:0;font-size:16px;font-weight:600;color:var(--foreground)}
27	.c-head p{margin:3px 0 0;font-size:13px;line-height:1.5;color:var(--muted-foreground)}
28	.stage{position:relative;background:var(--paper);color:var(--ink);border-radius:var(--radius);padding:18px 18px 12px;outline:none;border:1px solid transparent;overflow:hidden}
29	.stage:focus-visible,.stage:focus-within{border-color:color-mix(in srgb,var(--cobalt) 55%,transparent)}
30	.prose{font-family:var(--serif);font-size:17px;line-height:1.8;margin:0 0 .55em;color:var(--ink)}
31	.faint{color:var(--ink-2)}
32	.lock{border-radius:2px;background:color-mix(in srgb,var(--cobalt) 13%,transparent);box-shadow:inset 0 -2px 0 var(--cobalt)}
33	.idle{border-radius:2px;box-shadow:inset 0 -1px 0 color-mix(in srgb,var(--cobalt) 40%,transparent);cursor:pointer}
34	.status{margin:12px 0 0;padding-top:8px;border-top:1px solid var(--rule);font-family:var(--type);font-size:11px;line-height:1.5;color:var(--ink-3);min-height:2.4em}
35	.status b{color:var(--ink);font-weight:400}
36	.keys{margin:0;font-size:12px;line-height:1.9;color:var(--muted-foreground)}
37	.keys kbd{font-family:var(--font-mono);font-size:11px;padding:1px 5px;border:1px solid var(--border);border-radius:4px;background:var(--secondary);color:var(--secondary-foreground)}
38	.trade{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:0}
39	.trade dt{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted-foreground)}
40	.trade dd{margin:2px 0 0;font-size:13px;line-height:1.5;color:var(--foreground)}
41	.tag{font-family:var(--type);font-size:10px;color:var(--ink-3);white-space:nowrap}
42	ins.d{text-decoration:none;box-shadow:inset 0 -1px 0 color-mix(in srgb,var(--cobalt) 70%,transparent)}
43	.w{display:inline-block}
44	
45	/* Drum + tumblers */
46	.slot,.tum{position:relative;display:inline-block}
47	.slot .w,.tum .w{padding:0 .1em}
48	.ghost{position:absolute;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:.78em;line-height:1.45;color:var(--ink-3);background:var(--paper);padding:0 .35em;border-radius:3px;cursor:pointer;z-index:2}
49	.ghost:hover{color:var(--cobalt)}
50	.ghost.up{bottom:calc(100% - .2em)}
51	.ghost.down{top:calc(100% - .2em)}
52	.ghost:empty{display:none}
53	.slot.lock,.tum{cursor:ns-resize}
54	.tum{box-shadow:inset 0 -1px 0 color-mix(in srgb,var(--cobalt) 35%,transparent);border-radius:2px}
55	.tum.on{background:color-mix(in srgb,var(--cobalt) 13%,transparent);box-shadow:inset 0 -2px 0 var(--cobalt)}
56	.tum-line{padding:1.3em 0 1.1em;margin:0}
57	.whole{display:grid;gap:2px;margin:4px 0 0}
58	.whole p{margin:0 0 2px;font-family:var(--type);font-size:10px;color:var(--ink-3)}
59	.whole button{font-family:var(--serif);font-size:14px;line-height:1.45;text-align:left;background:none;border:0;border-left:2px solid transparent;padding:2px 8px;color:var(--ink-2);cursor:pointer}
60	.whole button:hover{border-left-color:var(--cobalt);color:var(--ink)}
61	
62	/* Margin */
63	.rail-grid{display:grid;grid-template-columns:minmax(0,1fr) 214px;gap:26px}
64	.rail{border-left:1px solid var(--rule);padding-left:12px;display:flex;flex-direction:column;gap:8px;min-width:0;transition:opacity .15s}
65	.rail.off{opacity:.35;pointer-events:none}
66	.chips{display:flex;flex-wrap:wrap;gap:2px}
67	.chips button{font-family:var(--type);font-size:10px;padding:2px 5px;border:1px solid transparent;background:none;color:var(--ink-2);cursor:pointer;border-radius:2px}
68	.chips button.on{border-color:color-mix(in srgb,var(--cobalt) 45%,transparent);background:color-mix(in srgb,var(--cobalt) 8%,transparent);color:var(--ink)}
69	.rail ol{list-style:none;margin:0;padding:0;display:grid;gap:1px;max-height:226px;overflow:auto;overscroll-behavior:contain}
70	.rail li{font-family:var(--serif);font-size:13px;line-height:1.4;padding:4px 7px;border-left:2px solid transparent;cursor:pointer;color:var(--ink)}
71	.rail li.on{border-left-color:var(--cobalt);background:color-mix(in srgb,var(--cobalt) 9%,transparent)}
72	.rail li .tag{display:block;margin-top:1px}
73	.rail li.orig{color:var(--ink-2)}
74	.steer input{width:100%;font-family:var(--type);font-size:11px;padding:5px 7px;border:1px solid var(--rule);background:var(--paper-soft);color:var(--ink);border-radius:3px;outline:none}
75	.steer input:focus{border-color:var(--cobalt)}
