83	.gloss kbd{font-family:var(--type);font-style:normal;font-size:10px;color:var(--ink-3)}
84	.gloss .tag{margin-left:auto;font-style:normal}
85	.gloss .more{font-family:var(--type);font-size:10px;color:var(--ink-3);background:none;border:0;padding:3px 6px;cursor:pointer;text-align:left}
