function lockDecorations(
  state: EditorState,
  value: PluginStateValue,
): DecorationSet {
  const lock = value.lock;
  if (!lock) return DecorationSet.empty;
  const previewing = value.preview !== null;
  const decorations = [
    Decoration.inline(lock.from, lock.to, {
      class: previewing
        ? "twyne-alt-lock twyne-alt-lock--previewing"
        : "twyne-alt-lock",
      "data-alternatives-lock": lock.id,
    }),
  ];
  if (previewing) {
    const text = value.preview!;
    decorations.push(
      Decoration.widget(
        lock.from,
        () => {
          const ghost = document.createElement("span");
          ghost.className = "twyne-alt-ghost";
          ghost.dataset.alternativesLock = lock.id;
          ghost.setAttribute("aria-hidden", "true");
          ghost.textContent = text;
          return ghost;
        },
        // A new preview must redraw the widget; equal keys are reused.
        { side: -1, key: `alt-ghost:${lock.id}:${text}` },
      ),
    );
  }
