230	function lockDecorations(
231	  state: EditorState,
232	  value: PluginStateValue,
233	): DecorationSet {
234	  const lock = value.lock;
235	  if (!lock) return DecorationSet.empty;
236	  const previewing = value.preview !== null;
237	  const decorations = [
