.twyne-alt-lock,
.twyne-alt-ghost {
  border-radius: 2px;
  background-color: color-mix(in srgb, var(--color-cobalt) 11%, transparent);
  box-shadow: inset 0 -1px 0
    color-mix(in srgb, var(--color-cobalt) 70%, transparent);
  cursor: ns-resize;
}
.twyne-alt-lock--previewing {
  display: none;
}
.twyne-alt-ghost {
  background-color: color-mix(in srgb, var(--color-cobalt) 17%, transparent);
  box-shadow: inset 0 -2px 0 var(--color-cobalt);
