  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.alt-drum__above,
.alt-drum__below {
  position: fixed;
  z-index: var(--z-dropdown);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.15rem;
  transform: translateX(-50%);
  pointer-events: none;
}
.alt-drum__pill {
  padding: 0 0.4em;
  border-radius: 3px;
  background: var(--color-paper);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--color-paper-3) 70%, transparent);
  color: var(--color-ink-muted);
  font-family: var(--font-serif);
  font-size: 0.8rem;
  line-height: 1.45;
  white-space: nowrap;
  pointer-events: auto;
  cursor: pointer;
}
.alt-drum__pill:hover {
  color: var(--color-cobalt);
}
.alt-drum__caption {
  padding: 0.05rem 0.4rem;
  border-radius: 3px;
  background: color-mix(in srgb, var(--color-paper) 92%, transparent);
  color: var(--color-ink-muted);
  font-family: var(--font-typewriter);
  font-size: 0.58rem;
  letter-spacing: 0.03em;
  white-space: nowrap;
}

/* Margin: a column of marginal notes beside the page. */
.alt-leader {
  position: fixed;
