  height: 100%;
  pointer-events: none;
  overflow: visible;
}
.alt-leader path {
  fill: none;
  stroke: var(--color-cobalt);
  stroke-width: 1;
  stroke-dasharray: 3 3;
  opacity: 0.75;
}
.alt-margin {
  position: fixed;
  z-index: var(--z-dropdown);
  display: flex;
  flex-direction: column;
  min-height: 0;
  gap: 0.35rem;
  color: var(--color-ink);
}
.alt-margin--right {
  padding-left: 0.75rem;
  border-left: 1px solid var(--color-paper-3);
}
.alt-margin--left {
  padding-right: 0.75rem;
  border-right: 1px solid var(--color-paper-3);
}
.alt-margin--sheet {
  padding: 0.5rem 0.6rem;
  border: 1px solid color-mix(in srgb, var(--color-ink-muted) 52%, transparent);
  background: color-mix(in srgb, var(--color-paper) 96%, transparent);
  box-shadow: 0 0.65rem 1.8rem rgba(32, 25, 16, 0.22);
  backdrop-filter: blur(14px) saturate(0.9);
}
.alt-margin__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}
.alt-margin__kicker {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.1rem 0.5rem;
  font-family: var(--font-typewriter);
  font-size: 0.6rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.alt-margin__kicker > span {
  color: var(--color-ink-muted);
  letter-spacing: 0.03em;
  text-transform: none;
}
