  padding: 0 0.3rem;
  color: var(--color-ink-muted);
  font-size: 0.9rem;
  line-height: 1;
}
.alt-margin__close:hover {
  color: var(--color-vermilion);
}
.alt-margin__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.1rem;
}
.alt-margin__chips > button {
  display: inline-flex;
  align-items: baseline;
  gap: 0.25rem;
  padding: 0.12rem 0.35rem;
  border: 1px solid transparent;
  border-radius: 2px;
  color: var(--color-ink-light);
  font-family: var(--font-typewriter);
  font-size: 0.6rem;
  white-space: nowrap;
}
.alt-margin__chips > button:hover {
  color: var(--color-cobalt);
}
.alt-margin__chips > button.is-on {
  border-color: color-mix(in srgb, var(--color-cobalt) 45%, transparent);
  background: color-mix(in srgb, var(--color-cobalt) 8%, transparent);
  color: var(--color-ink);
}
.alt-margin__count {
  color: var(--color-ink-muted);
  font-size: 0.55rem;
}
.alt-margin__list {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  outline: none;
  display: grid;
  align-content: start;
  gap: 1px;
}
.alt-margin__list:focus-visible {
  box-shadow: inset 2px 0 0
    color-mix(in srgb, var(--color-cobalt) 45%, transparent);
}
.alt-margin__option {
  padding: 0.3rem 0.45rem;
  border-left: 2px solid transparent;
  cursor: pointer;
}
.alt-margin__option.is-active {
  border-left-color: var(--color-cobalt);
  background: color-mix(in srgb, var(--color-cobalt) 9%, transparent);
}
.alt-margin__text {
  display: block;
  color: var(--color-ink);
  font-family: var(--font-serif);
  font-size: 0.86rem;
  line-height: 1.42;
  overflow-wrap: anywhere;
}
.alt-margin__text em {
  font-style: normal;
  box-shadow: inset 0 -1px 0
    color-mix(in srgb, var(--color-cobalt) 65%, transparent);
}
.alt-margin__option--original .alt-margin__text {
  color: var(--color-ink-light);
}
.alt-margin__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0 0.45rem;
  margin-top: 0.05rem;
  color: var(--color-ink-muted);
  font-family: var(--font-typewriter);
  font-size: 0.56rem;
  letter-spacing: 0.03em;
}
.alt-margin__empty,
.alt-margin__more {
  display: block;
  width: 100%;
  padding: 0.4rem 0.45rem;
  color: var(--color-ink-muted);
  font-family: var(--font-typewriter);
  font-size: 0.62rem;
  text-align: left;
}
.alt-margin__more--button:hover {
  color: var(--color-cobalt);
}
.alt-margin__notice {
  color: var(--color-ink-light);
  font-family: var(--font-typewriter);
  font-size: 0.6rem;
  line-height: 1.45;
}
.alt-margin__steer input {
  width: 100%;
  padding: 0.3rem 0.45rem;
  border: 1px solid var(--color-paper-3);
  border-radius: 3px;
  background: var(--color-paper-soft);
  color: var(--color-ink);
  font-family: var(--font-typewriter);
  font-size: 0.66rem;
  outline: none;
}
.alt-margin__steer input:focus {
  border-color: var(--color-cobalt);
}
.alt-margin__steer input:disabled {
  opacity: 0.6;
}
.alt-margin__keys {
  display: flex;
  flex-wrap: wrap;
  gap: 0.1rem 0.6rem;
  color: var(--color-ink-muted);
  font-family: var(--font-typewriter);
  font-size: 0.55rem;
}
.alt-margin__position {
  margin-left: auto;
}
.alt-refusal {
  position: fixed;
  z-index: var(--z-dropdown);
  padding: 0.45rem 0.65rem;
  border: 1px solid color-mix(in srgb, var(--color-ink-muted) 52%, transparent);
  background: color-mix(in srgb, var(--color-paper) 96%, transparent);
  box-shadow: 0 0.5rem 1.4rem rgba(32, 25, 16, 0.18);
  color: var(--color-ink-light);
  font-family: var(--font-typewriter);
  font-size: 0.66rem;
  line-height: 1.45;
}
@media (pointer: coarse) {
  .alt-margin__keys {
    display: none;
  }
  .alt-margin__option {
    padding-block: 0.5rem;
  }
  .alt-drum__pill {
    padding: 0.15em 0.6em;
    font-size: 0.9rem;
  }
}
@media print {
  .alt-drum__above,
  .alt-drum__below,
  .alt-margin,
  .alt-leader,
  .alt-refusal,
  .twyne-alt-ghost {
    display: none !important;
  }
  .twyne-alt-lock,
  .twyne-alt-lock--previewing {
    display: inline !important;
    background: none !important;
    box-shadow: none !important;
  }
}

