import { chromium } from "/home/diogenes/Projects/apps/twyne/node_modules/playwright/index.mjs";

const BASE = "http://127.0.0.1:5174";
const OUT = "/tmp/claude-1000/-home-diogenes-Projects-apps-twyne/e8f36531-c27d-4be0-9028-f9a9a68a26ed/scratchpad";
const HTML =
  "<p>Morning came early to the valley, and the bells started before anyone was ready for them.</p>" +
  "<p>It was a happy day for the whole village, and nobody wanted it to end.</p>" +
  "<p>The old house stood alone at the end of the lane, its shutters closed against the wind.</p>";

const sse = (text) => {
  const chunk = (delta, finish = null) =>
    `data: ${JSON.stringify({ id: "s", object: "chat.completion.chunk", created: 0, model: "stub-model", choices: [{ index: 0, delta, finish_reason: finish }] })}\n\n`;
  const parts = text.match(/[\s\S]{1,40}/g) ?? [];
  return chunk({ role: "assistant", content: "" }) + parts.map((p) => chunk({ content: p })).join("") + chunk({}, "stop") + "data: [DONE]\n\n";
};
const WORD = [
  { lens: "synonym", text: "joyful" }, { lens: "synonym", text: "glad" }, { lens: "synonym", text: "sunlit" },
  { lens: "antonym", text: "bleak" }, { lens: "slot", text: "busy" },
];
const PHRASE = [
  { lens: "rephrase", text: "The empty house" }, { lens: "rephrase", text: "The aging farmhouse" },
  { lens: "plainer", text: "The old home" }, { lens: "sharper", text: "The gray clapboard house" },
  { lens: "formal", text: "The ancestral residence" }, { lens: "looser", text: "That creaky old place" },
  { lens: "opposite", text: "The new house" },
];
const STEERED = [{ lens: "steered", text: "The forsaken house" }, { lens: "steered", text: "The lonesome house" }, { lens: "rephrase", text: "should be dropped" }];

const log = (...a) => console.log(...a);
const requests = [];

async function run(width, label) {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width, height: 860 } });
  page.on("pageerror", (e) => log("PAGEERROR", e.message));
  page.on("console", (m) => {
    if (m.type() === "error" && !/favicon|posthog|convex|Failed to load resource|CORS/i.test(m.text())) log("CONSOLE", m.text().slice(0, 240));
  });
  await page.route(/\/api\/auth\//, (r) => r.fulfill({ contentType: "application/json", body: "null" }));
  await page.route("**/__alt-seed", (r) => r.fulfill({ contentType: "text/html", body: "<!doctype html><title>seed</title>" }));
  await page.route("**/stub-llm/v1/**", async (route) => {
    const body = JSON.stringify(route.request().postDataJSON());
    requests.push(body);
    const lines = body.includes("lonelier") ? STEERED : body.includes('SPAN: \\"happy\\"') ? WORD : PHRASE;
    await route.fulfill({ status: 200, headers: { "content-type": "text/event-stream" }, body: sse(lines.map((l) => JSON.stringify(l)).join("\n")) });
  });
  await page.goto(`${BASE}/__alt-seed`);
  await page.evaluate(async (html) => {
    const db = await import(/* @vite-ignore */ "/src/utils/idb.ts");
    const now = Date.now(), id = "alt-fixture-2";
    await db.saveFoliosToIdb([{ id, name: "Alternatives check", type: "draft", createdAt: now, updatedAt: now }]);
    await db.saveFolioContentToIdb(id, html);
    await db.saveActiveFolioIdToIdb(id);
    await db.saveMetaToIdb("live-review-enabled", false);
    await db.saveMetaToIdb("signin-toast-dismissed", true);
    await db.saveAiSettingsToIdb({
      advancedMode: true,
      providers: [{ id: "stub", name: "Stub", type: "openai-compatible", apiKey: "x", baseUrl: `${location.origin}/stub-llm/v1`, defaultModel: "stub-model", apiMode: "chat" }],
      defaultProviderId: "stub", perFeature: {}, showProviderTags: false,
    });
    localStorage.setItem("living-desk-open", "false");
    localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
  }, HTML);
  await page.goto(`${BASE}/editor/`);
  const pm = page.locator("#twyne-editor-mount .ProseMirror");
  await pm.getByText("It was a happy day").waitFor({ timeout: 90_000 });
  await page.waitForTimeout(1500);

  const textRect = (paraIndex, needle) => page.evaluate(([i, n]) => {
    const p = document.querySelectorAll("#twyne-editor-mount .ProseMirror p")[i];
    const w = document.createTreeWalker(p, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = w.nextNode())) {
      const k = node.data.indexOf(n);
      if (k >= 0) { const r = document.createRange(); r.setStart(node, k); r.setEnd(node, k + n.length); const b = r.getBoundingClientRect(); return { x: b.left + b.width / 2, y: b.top + b.height / 2 }; }
    }
  }, [paraIndex, needle]);
  const select = (paraIndex, needle) => page.evaluate(([i, n]) => {
    const p = document.querySelectorAll("#twyne-editor-mount .ProseMirror p")[i];
    const w = document.createTreeWalker(p, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = w.nextNode())) {
      const k = node.data.indexOf(n);
      if (k >= 0) { const r = document.createRange(); r.setStart(node, k); r.setEnd(node, k + n.length); getSelection().removeAllRanges(); getSelection().addRange(r); return; }
    }
  }, [paraIndex, needle]);

  // ── Drum ──
  const h = await textRect(1, "happy");
  await page.mouse.dblclick(h.x, h.y);
  await page.locator(".selection-actions button", { hasText: "Alternatives" }).click();
  await page.locator(".alt-drum").waitFor({ timeout: 10_000 });
  await page.waitForFunction(() => document.querySelectorAll(".alt-drum__options [role=option]").length > 6, null, { timeout: 15_000 }).catch(() => {});
  await page.waitForTimeout(600);
  log(`[${label}] drum caption:`, await page.locator(".alt-drum__caption").innerText());
  log(`[${label}] focus in drum:`, await page.evaluate(() => !!document.activeElement?.closest(".alt-drum")));
  await page.keyboard.press("ArrowDown"); await page.keyboard.press("ArrowDown");
  await page.waitForTimeout(250);
  log(`[${label}] after 2 down — word:`, await page.locator(".twyne-alt-ghost").innerText(), "| above:", await page.locator(".alt-drum__above").innerText(), "| below:", (await page.locator(".alt-drum__below .alt-drum__pill").innerText().catch(() => "-")), "|", await page.locator(".alt-drum__caption").innerText());
  await page.screenshot({ path: `${OUT}/v2-${label}-drum.png` });
  // Click the faded next word.
  await page.locator(".alt-drum__below .alt-drum__pill").click();
  await page.waitForTimeout(200);
  log(`[${label}] after clicking next pill:`, await page.locator(".twyne-alt-ghost").innerText());
  // Wheel on the word.
  const g = await page.locator(".twyne-alt-ghost").boundingBox();
  await page.mouse.move(g.x + g.width / 2, g.y + g.height / 2);
  await page.mouse.wheel(0, 120); await page.waitForTimeout(200);
  log(`[${label}] after wheel:`, await page.locator(".twyne-alt-ghost").innerText());
  // Jump to antonyms with →.
  await page.locator(".alt-drum__options").focus();
  for (let k = 0; k < 3; k++) await page.keyboard.press("ArrowRight");
  await page.waitForTimeout(200);
  log(`[${label}] after 3x right:`, await page.locator(".twyne-alt-ghost").innerText(), "|", await page.locator(".alt-drum__caption").innerText());
  await page.keyboard.press("Enter"); await page.waitForTimeout(300);
  log(`[${label}] applied:`, (await pm.locator("p").nth(1).innerText()).slice(0, 26), "| drum gone:", (await page.locator(".alt-drum").count()) === 0);
  await page.keyboard.press("Control+z"); await page.waitForTimeout(300);

  // ── Margin ──
  await select(2, "The old house");
  await page.waitForTimeout(300);
  await page.keyboard.press("Shift+F7");
  const margin = page.locator(".alt-margin");
  await margin.waitFor({ timeout: 10_000 });
  await page.waitForFunction(() => document.querySelectorAll(".alt-margin__option").length > 4, null, { timeout: 15_000 }).catch(() => {});
  await page.waitForTimeout(500);
  log(`[${label}] margin side:`, await margin.getAttribute("class"));
  const mb = await margin.boundingBox();
  const pageBox = await page.locator(".page-canvas").boundingBox();
  log(`[${label}] margin box x=${Math.round(mb.x)} w=${Math.round(mb.width)} | page right=${Math.round(pageBox.x + pageBox.width)} | overlaps page:`, mb.x < pageBox.x + pageBox.width && mb.x + mb.width > pageBox.x);
  await page.keyboard.press("ArrowDown"); await page.keyboard.press("ArrowDown");
  await page.waitForTimeout(300);
  log(`[${label}] margin preview:`, await page.locator(".twyne-alt-ghost").innerText(), "| leader:", await page.locator(".alt-leader path").count());
  await page.screenshot({ path: `${OUT}/v2-${label}-margin.png` });
  // Steer.
  await page.locator(".alt-margin__steer input").fill("lonelier");
  await page.keyboard.press("Enter");
  await page.waitForFunction(() => [...document.querySelectorAll(".alt-margin__option")].some((o) => o.innerText.includes("lonesome")), null, { timeout: 10_000 }).catch(() => {});
  await page.waitForTimeout(300);
  log(`[${label}] steered list:`, JSON.stringify(await page.locator(".alt-margin__option").evaluateAll((els) => els.map((e) => e.innerText.replace(/\s+/g, " ").trim()))));
  log(`[${label}] chips:`, JSON.stringify(await page.locator(".alt-margin__chips button").allInnerTexts()));
  await page.locator(".alt-margin__list").focus();
  await page.keyboard.press("ArrowDown");
  await page.waitForTimeout(200);
  await page.screenshot({ path: `${OUT}/v2-${label}-steer.png` });
  await page.keyboard.press("Enter"); await page.waitForTimeout(300);
  log(`[${label}] applied steer:`, (await pm.locator("p").nth(2).innerText()).slice(0, 30), "| margin gone:", (await margin.count()) === 0, "| leader gone:", (await page.locator(".alt-leader").count()) === 0);
  await browser.close();
}

await run(1440, "wide");
await run(820, "narrow");
log("model requests:", requests.length, "| steer request has direction:", requests.some((r) => r.includes("lonelier") && r.includes("steered")));

