/** Width of what currently shows for the lock: its preview, or its words. */
function shownWidth(root: ParentNode, id: string): number | null {
  let left = Infinity;
  let right = -Infinity;
  for (const el of root.querySelectorAll<HTMLElement>(
    `[data-alternatives-lock="${id}"]`,
