  .alt-drum__pill.is-roll-up {
    animation: alt-from-above 200ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }
  .alt-drum__above .alt-drum__pill.is-roll-up {
    animation-name: alt-from-above;
  }
  .alt-drum__below .alt-drum__pill.is-roll-down {
    animation-name: alt-from-below;
  }
  .alt-drum__pill.is-pending {
    animation: alt-pulse 1.1s ease-in-out infinite;
  }
  .alt-drum__caption {
    animation: alt-pop 220ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }
  .alt-drum.is-leaving .alt-drum__pill,
  .alt-drum.is-leaving .alt-drum__caption {
    animation: alt-fade-out 140ms ease-in both;
  }

  /* Margin */
  .alt-margin--right {
    animation: alt-from-page-right 240ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }
  .alt-margin--left {
    animation: alt-from-page-left 240ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }
  .alt-margin--sheet {
    animation: alt-sheet-in 220ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }
  .alt-margin--right.is-leaving {
    animation: alt-to-page-right 150ms ease-in both;
  }
  .alt-margin--left.is-leaving {
    animation: alt-to-page-left 150ms ease-in both;
  }
  .alt-margin--sheet.is-leaving {
    animation: alt-sheet-out 150ms ease-in both;
  }
  .alt-margin__option {
    transition: background-color 140ms ease-out;
    animation: alt-option-in 240ms cubic-bezier(0.22, 1, 0.36, 1) both;
    animation-delay: calc(var(--i, 0) * 26ms);
  }
  .alt-margin__option--original {
    animation: none;
  }
  .alt-margin__cursor {
    transition:
      translate 170ms cubic-bezier(0.22, 1, 0.36, 1),
      height 170ms cubic-bezier(0.22, 1, 0.36, 1);
  }
  .alt-leader {
    animation: alt-fade-in 220ms ease-out both;
  }
  .alt-leader path {
    transition: d 170ms cubic-bezier(0.22, 1, 0.36, 1);
  }
  .alt-leader.is-busy path {
    animation: alt-march 0.6s linear infinite;
  }
  .alt-margin__count,
  .alt-margin__chips > button[data-lens="steered"] {
    animation: alt-pop 220ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }
  .alt-margin__skeleton > span {
    animation: alt-shimmer 1.3s ease-in-out infinite;
  }
  .alt-margin__steer.is-busy input {
    background-image: linear-gradient(
      90deg,
      transparent 30%,
      color-mix(in srgb, var(--color-cobalt) 10%, transparent) 50%,
      transparent 70%
    );
    background-size: 300% 100%;
    animation: alt-shimmer 1.1s ease-in-out infinite;
  }
  .alt-refusal {
    animation: alt-shake 380ms ease-out both;
  }
}
@keyframes alt-in-from-below {
