import { chromium } from "/home/diogenes/Projects/apps/twyne/node_modules/playwright/index.mjs";

const BASE = "http://127.0.0.1:5174";
const OUT = "/tmp/claude-1000/-home-diogenes-Projects-apps-twyne/e8f36531-c27d-4be0-9028-f9a9a68a26ed/scratchpad";
const HTML =
  "<p>Morning came early to the valley, and the bells started before anyone was ready for them.</p>" +
  "<p>It was a happy day for the whole village, and nobody wanted it to end.</p>" +
  "<p>The old house stood alone at the end of the lane, its shutters closed against the wind.</p>";
const sse = (text) => {
  const chunk = (delta, finish = null) => `data: ${JSON.stringify({ id: "s", object: "chat.completion.chunk", created: 0, model: "m", choices: [{ index: 0, delta, finish_reason: finish }] })}\n\n`;
  return chunk({ role: "assistant", content: "" }) + (text.match(/[\s\S]{1,40}/g) ?? []).map((p) => chunk({ content: p })).join("") + chunk({}, "stop") + "data: [DONE]\n\n";
};
const WORD = [["synonym", "joyful"], ["synonym", "glad"], ["synonym", "sunlit"], ["antonym", "bleak"], ["slot", "busy"]];
const PHRASE = [["rephrase", "The empty house"], ["rephrase", "The aging farmhouse"], ["plainer", "The old home"], ["sharper", "The gray clapboard house"], ["formal", "The ancestral residence"], ["looser", "That creaky old place"], ["opposite", "The new house"]];
const log = (...a) => console.log(...a);

async function session(reduced) {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 860 }, reducedMotion: reduced ? "reduce" : "no-preference" });
  const page = await ctx.newPage();
  page.on("pageerror", (e) => log("PAGEERROR", e.message));
  await page.route(/\/api\/auth\//, (r) => r.fulfill({ contentType: "application/json", body: "null" }));
  await page.route("**/__alt-seed", (r) => r.fulfill({ contentType: "text/html", body: "<!doctype html><title>seed</title>" }));
  await page.route("**/stub-llm/v1/**", async (route) => {
    const body = JSON.stringify(route.request().postDataJSON());
    const lines = body.includes('SPAN: \\"happy\\"') ? WORD : PHRASE;
    await new Promise((r) => setTimeout(r, 700)); // long enough to see loading states
    await route.fulfill({ status: 200, headers: { "content-type": "text/event-stream" }, body: sse(lines.map(([lens, text]) => JSON.stringify({ lens, text })).join("\n")) });
  });
  await page.goto(`${BASE}/__alt-seed`);
  await page.evaluate(async (html) => {
    const db = await import(/* @vite-ignore */ "/src/utils/idb.ts");
    const now = Date.now(), id = "alt-motion";
    await db.saveFoliosToIdb([{ id, name: "Motion", type: "draft", createdAt: now, updatedAt: now }]);
    await db.saveFolioContentToIdb(id, html);
    await db.saveActiveFolioIdToIdb(id);
    await db.saveMetaToIdb("live-review-enabled", false);
    await db.saveMetaToIdb("signin-toast-dismissed", true);
    await db.saveAiSettingsToIdb({ advancedMode: true, providers: [{ id: "stub", name: "Stub", type: "openai-compatible", apiKey: "x", baseUrl: `${location.origin}/stub-llm/v1`, defaultModel: "m", apiMode: "chat" }], defaultProviderId: "stub", perFeature: {}, showProviderTags: false });
    localStorage.setItem("living-desk-open", "false");
    localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
  }, HTML);
  await page.goto(`${BASE}/editor/`);
  const pm = page.locator("#twyne-editor-mount .ProseMirror");
  await pm.getByText("It was a happy day").waitFor({ timeout: 90_000 });
  await page.waitForTimeout(1200);
  return { browser, page, pm };
}
const select = (page, i, needle) => page.evaluate(([i, n]) => {
  const p = document.querySelectorAll("#twyne-editor-mount .ProseMirror p")[i];
  const w = document.createTreeWalker(p, NodeFilter.SHOW_TEXT); let node;
  while ((node = w.nextNode())) { const k = node.data.indexOf(n); if (k >= 0) { const r = document.createRange(); r.setStart(node, k); r.setEnd(node, k + n.length); getSelection().removeAllRanges(); getSelection().addRange(r); return; } }
}, [i, needle]);
// Which animations are running right now, by element class.
const running = (page) => page.evaluate(() => document.getAnimations().filter((a) => a.playState === "running").map((a) => {
  const t = a.effect?.target; const name = a.animationName ?? (a.transitionProperty ? `transition:${a.transitionProperty}` : "waapi");
  const cls = t?.className?.baseVal ?? t?.className ?? ""; return `${name}@${String(cls).split(" ").filter((c) => c.startsWith("twyne-alt") || c.startsWith("alt-")).join(".")}`;
}).filter((s) => /alt/.test(s)));

// ── Full motion ──
{
  const { browser, page, pm } = await session(false);
  await select(page, 1, "happy");
  await page.waitForTimeout(200);
  await page.keyboard.press("Shift+F7");
  await page.waitForTimeout(40);
  log("open (sweep):", JSON.stringify(await running(page)));
  await page.waitForFunction(() => document.querySelectorAll(".alt-drum__options [role=option]").length > 6, null, { timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(500);
  await page.keyboard.press("ArrowDown");
  await page.waitForTimeout(60);
  log("step down (roll):", JSON.stringify(await running(page)));
  const clip = async (name) => { const b = await page.locator(".twyne-alt-ghost").boundingBox(); await page.screenshot({ path: `${OUT}/${name}.png`, clip: { x: b.x - 120, y: b.y - 50, width: b.width + 340, height: 110 } }); };
  // Frame strip of one roll.
  await page.keyboard.press("ArrowDown"); await page.waitForTimeout(25); await clip("m-roll-1");
  await page.waitForTimeout(55); await clip("m-roll-2");
  await page.waitForTimeout(250); await clip("m-roll-3");
  // Bump at the top.
  await page.keyboard.press("Home"); await page.waitForTimeout(250);
  await page.keyboard.press("ArrowUp"); await page.waitForTimeout(40);
  log("up at top (nudge):", JSON.stringify(await running(page)));
  // Apply: ink dries.
  await page.keyboard.press("ArrowDown"); await page.waitForTimeout(250);
  await page.keyboard.press("Enter"); await page.waitForTimeout(60);
  log("applied (ink):", JSON.stringify(await running(page)), "| applied deco:", await page.locator(".twyne-alt-applied").count());
  await page.waitForTimeout(1100);
  log("after dry: applied deco left:", await page.locator(".twyne-alt-applied").count());

  // Margin.
  await select(page, 2, "The old house");
  await page.waitForTimeout(200);
  await page.keyboard.press("Shift+F7");
  await page.waitForTimeout(80);
  log("margin open (slide + skeleton):", JSON.stringify(await running(page)));
  await page.screenshot({ path: `${OUT}/m-margin-loading.png`, clip: { x: 1080, y: 280, width: 360, height: 220 } });
  await page.waitForFunction(() => document.querySelectorAll(".alt-margin__option").length > 4, null, { timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(60);
  log("options arrive (stagger):", JSON.stringify(await running(page)).slice(0, 400));
  await page.waitForTimeout(600);
  await page.keyboard.press("ArrowDown"); await page.keyboard.press("ArrowDown");
  await page.waitForTimeout(50);
  log("margin step (cursor, leader, ink):", JSON.stringify(await running(page)));
  await page.waitForTimeout(300);
  await page.screenshot({ path: `${OUT}/m-margin.png`, clip: { x: 340, y: 280, width: 1100, height: 520 } });
  await page.keyboard.press("Escape"); await page.waitForTimeout(40);
  log("escape (leave):", JSON.stringify(await running(page)), "| still in DOM:", await page.locator(".alt-margin").count());
  await page.waitForTimeout(300);
  log("after leave, in DOM:", await page.locator(".alt-margin").count());

  // Refusal shake.
  await page.evaluate(() => {
    const ps = document.querySelectorAll("#twyne-editor-mount .ProseMirror p");
    const t = (p) => { const w = document.createTreeWalker(p, NodeFilter.SHOW_TEXT); let n; while ((n = w.nextNode())) if (n.data.length > 6) return n; };
    const r = document.createRange(); r.setStart(t(ps[1]), 3); r.setEnd(t(ps[2]), 5); getSelection().removeAllRanges(); getSelection().addRange(r);
  });
  await page.waitForTimeout(200);
  await page.keyboard.press("Escape"); // drop the selection card so the refusal shows at the caret
  await page.keyboard.press("Shift+F7"); await page.waitForTimeout(60);
  log("refusal:", JSON.stringify(await running(page)), await page.locator(".alt-refusal, .selection-actions__error").allInnerTexts());
  await browser.close();
}

// ── Reduced motion ──
{
  const { browser, page } = await session(true);
  await select(page, 1, "happy");
  await page.waitForTimeout(200);
  await page.keyboard.press("Shift+F7");
  await page.waitForFunction(() => document.querySelectorAll(".alt-drum__options [role=option]").length > 6, null, { timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(400);
  await page.keyboard.press("ArrowDown"); await page.waitForTimeout(40);
  log("[reduced] step:", JSON.stringify(await running(page)), "| word:", await page.locator(".twyne-alt-ghost").innerText());
  await page.keyboard.press("Escape"); await page.waitForTimeout(40);
  log("[reduced] closes at once:", await page.locator(".alt-drum").count() === 0);
  await select(page, 2, "The old house"); await page.waitForTimeout(200);
  await page.keyboard.press("Shift+F7"); await page.waitForTimeout(80);
  log("[reduced] margin open:", JSON.stringify(await running(page)));
  await browser.close();
}

