import sys, re, subprocess
KEY = re.compile(r"lternativ|Shift-F7|ALTERNATIVES|alt-|twyne-alt|openAlternatives")
def hunks(path):
    out = subprocess.run(["git","--no-pager","diff","--no-color","-U0","HEAD","--",path],capture_output=True,text=True,check=True).stdout
    lines = out.splitlines(keepends=True)
    head, cur, hs = [], None, []
    for l in lines:
        if l.startswith("@@"):
            if cur: hs.append(cur)
            cur=[l]
        elif cur is None: head.append(l)
        else: cur.append(l)
    if cur: hs.append(cur)
    return head, hs
path = sys.argv[1]; show = len(sys.argv)>2
head, hs = hunks(path)
keep = [h for h in hs if KEY.search("".join(h[1:]))]
if show:
    for h in keep: sys.stdout.write("".join(h)+"\n=====\n")
else:
    sys.stdout.write("".join(head)+"".join("".join(h) for h in keep))
EOF
