"""Port only the Alternatives feature from the working tree into a clean checkout.

usage: python3 port.py SRC DEST
  SRC   the working tree with Alternatives and unrelated uncommitted work
  DEST  a clean checkout (HEAD) to receive Alternatives alone
"""
import os, re, shutil, subprocess, sys

SRC, DEST = sys.argv[1], sys.argv[2]
KEY = re.compile(r"lternativ|Shift-F7|ALTERNATIVES|alt-|twyne-alt|openAlternatives")

NEW_FILES = [
    "src/utils/alternatives.ts",
    "src/utils/alternatives.test.ts",
    "src/components/editor/extensions/alternatives.ts",
    "src/components/editor/extensions/alternatives.test.ts",
    "src/components/editor/alternatives-palette.tsx",
    "convex/alternatives.ts",
    "prompts/alternatives-system.md",
    "prompts/alternatives-user.md",
]
# Files whose Alternatives hunks are clean insertions, separate from other work.
HUNK_FILES = [
    "src/components/editor/selection-actions.tsx",
    "src/components/editor/selection-actions.stories.tsx",
    "src/global.css",
    "src/utils/ai-client.ts",
    "src/types/index.ts",
    "src/utils/usage-domain.ts",
    "src/routes/settings/index.tsx",
    "src/utils/editor-commands.ts",
    "src/utils/keybindings.ts",
    "convex/lib/rateLimit.ts",
    "convex/_generated/api.d.ts",
]


def run(*args, cwd, **kw):
    return subprocess.run(args, cwd=cwd, check=True, text=True, capture_output=True, **kw).stdout


for rel in NEW_FILES:
    os.makedirs(os.path.dirname(os.path.join(DEST, rel)), exist_ok=True)
    shutil.copyfile(os.path.join(SRC, rel), os.path.join(DEST, rel))


def filtered_patch(rel):
    out = run("git", "--no-pager", "diff", "--no-color", "-U0", "HEAD", "--", rel, cwd=SRC)
    head, cur, hunks = [], None, []
    for line in out.splitlines(keepends=True):
        if line.startswith("@@"):
            if cur:
                hunks.append(cur)
            cur = [line]
        elif cur is None:
            head.append(line)
        else:
            cur.append(line)
    if cur:
        hunks.append(cur)
    keep = [h for h in hunks if KEY.search("".join(h[1:]))]
    return "".join(head) + "".join("".join(h) for h in keep), len(keep), len(hunks)


for rel in HUNK_FILES:
    run("git", "checkout", "HEAD", "--", rel, cwd=DEST)  # rerunnable
    patch, kept, total = filtered_patch(rel)
    if not kept:
        sys.exit(f"no Alternatives hunks in {rel}")
    subprocess.run(
        ["git", "apply", "--unidiff-zero", "-"], cwd=DEST, input=patch, text=True, check=True
    )
    print(f"{rel}: {kept}/{total} hunks")

# The editor shell: the owner's uncommitted refactor reindented the block the
# registration sits in, so these edits are made against HEAD by hand.
rel = "src/components/editor/twyne-editor.tsx"
run("git", "checkout", "HEAD", "--", rel, cwd=DEST)
path = os.path.join(DEST, rel)
s = open(path).read()


def sub(pattern, repl, flags=0):
    global s
    s2, n = re.subn(pattern, repl, s, count=1, flags=flags)
    if n != 1:
        sys.exit(f"twyne-editor.tsx: anchor not found: {pattern[:60]}")
    s = s2


sub(
    r'(import \{ FindReplace \} from "\./extensions/find-replace";\n)',
    r'\1import {\n  Alternatives,\n  alternativesController,\n  alternativesSnapshot,\n} from "./extensions/alternatives";\nimport { AlternativesPalette } from "./alternatives-palette";\n',
)
sub(r"(\n(\s+)FindReplace,\n)", r"\1\2Alternatives,\n")
sub(
    r"( +)if \(nativeTextDragActive \|\| threadInstrumentSnapshot\(\)\.open\) \{",
    lambda m: f"{m.group(1)}if (\n{m.group(1)}  nativeTextDragActive ||\n{m.group(1)}  threadInstrumentSnapshot().open ||\n{m.group(1)}  alternativesSnapshot()\n{m.group(1)}) {{",
)
sub(
    r'(\n( +)case "review\.read-aloud":\n +await readAloud\(\);\n +break;\n)',
    lambda m: m.group(1)
    + f'{m.group(2)}case "review.alternatives":\n{m.group(2)}  openAlternatives(undefined);\n{m.group(2)}  break;\n',
)
open_fn = '''    /**
     * Lock a span for Alternatives: the given range, the selection, or the
     * word at the caret. A span that cannot be locked says why on the
     * selection card, or at the caret when there is no card.
     */
    const openAlternatives = $(
      (range: { from: number; to: number } | undefined) => {
        if (readOnly || !store.editor) return;
        const result = alternativesController()?.open(range);
        if (!result) return;
        if (result.ok) {
          store.selectionAction = null;
          return;
        }
        const current = store.selectionAction;
        if (current)
          store.selectionAction = { ...current, error: result.message };
        else alternativesController()?.refuse(result.message);
      },
    );

'''
sub(r"(\n)(    const runRegistryCommand = \$\()", lambda m: m.group(1) + open_fn + m.group(2))
sub(
    r"(\n( +)onSentenceBench\$=\{\(\) => \{)",
    lambda m: f"\n{m.group(2)}onAlternatives$={{() => {{\n{m.group(2)}  const selection = store.selectionAction;\n{m.group(2)}  openAlternatives(\n{m.group(2)}    selection ? {{ from: selection.from, to: selection.to }} : undefined,\n{m.group(2)}  );\n{m.group(2)}}}}}"
    + m.group(1),
)
sub(
    r"(\n( +)\{store\.activeFolioId && \(\n +<InstrumentDock)",
    lambda m: f"\n{m.group(2)}<AlternativesPalette />\n" + m.group(1),
)
open(path, "w").write(s)
print(f"{rel}: hand-applied")

run("bun", "scripts/compile-prompts.ts", cwd=DEST)
print("prompt catalog compiled")

