"""Port only the Alternatives feature from the working tree into a clean checkout.

usage: python3 port.py SRC DEST
  SRC   the working tree with Alternatives and unrelated uncommitted work
  DEST  a clean checkout (HEAD) to receive Alternatives alone
"""
import os, re, shutil, subprocess, sys

SRC, DEST = sys.argv[1], sys.argv[2]
KEY = re.compile(r"lternativ|Shift-F7|ALTERNATIVES|alt-|twyne-alt|openAlternatives")

NEW_FILES = [
    "src/utils/alternatives.ts",
    "src/utils/alternatives.test.ts",
    "src/components/editor/extensions/alternatives.ts",
    "src/components/editor/extensions/alternatives.test.ts",
    "src/components/editor/alternatives-palette.tsx",
    "convex/alternatives.ts",
    "prompts/alternatives-system.md",
    "prompts/alternatives-user.md",
]
# Files whose Alternatives hunks are clean insertions, separate from other work.
HUNK_FILES = [
    "src/components/editor/selection-actions.tsx",
    "src/components/editor/selection-actions.stories.tsx",
    "src/global.css",
    "src/utils/ai-client.ts",
    "src/types/index.ts",
    "src/utils/usage-domain.ts",
    "src/routes/settings/index.tsx",
    "src/utils/editor-commands.ts",
    "src/utils/keybindings.ts",
    "convex/lib/rateLimit.ts",
    "convex/_generated/api.d.ts",
]


def run(*args, cwd, **kw):
    return subprocess.run(args, cwd=cwd, check=True, text=True, capture_output=True, **kw).stdout


for rel in NEW_FILES:
    os.makedirs(os.path.dirname(os.path.join(DEST, rel)), exist_ok=True)
    shutil.copyfile(os.path.join(SRC, rel), os.path.join(DEST, rel))


def filtered_patch(rel):
    out = run("git", "--no-pager", "diff", "--no-color", "-U0", "HEAD", "--", rel, cwd=SRC)
    head, cur, hunks = [], None, []
    for line in out.splitlines(keepends=True):
        if line.startswith("@@"):
            if cur:
                hunks.append(cur)
            cur = [line]
        elif cur is None:
            head.append(line)
        else:
            cur.append(line)
    if cur:
        hunks.append(cur)
    keep = [h for h in hunks if KEY.search("".join(h[1:]))]
    return "".join(head) + "".join("".join(h) for h in keep), len(keep), len(hunks)


for rel in HUNK_FILES:
    run("git", "checkout", "HEAD", "--", rel, cwd=DEST)  # rerunnable
    patch, kept, total = filtered_patch(rel)
    if not kept:
        sys.exit(f"no Alternatives hunks in {rel}")
    subprocess.run(
        ["git", "apply", "--unidiff-zero", "-"], cwd=DEST, input=patch, text=True, check=True
    )
    print(f"{rel}: {kept}/{total} hunks")

