import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { brotliCompressSync } from 'node:zlib';
const name=process.argv[2];
if (!['provider','twyne'].includes(name)) throw Error('Unknown target');
const dryRun=process.argv[3] !== '--deploy';
const base='/home/diogenes/.t3/scratch/voice-repair-release-20261106';
const request=JSON.parse(readFileSync(`${base}/${name}-scoped-request.json`,'utf8'));
const baseline=JSON.parse(readFileSync(`${base}/${name}-live-config.json`,'utf8'));
const deploymentName=name==='provider'?'courteous-horse-754':'hushed-aardvark-411';
const url=`https://${deploymentName}.convex.cloud`;
const response=await fetch(url+'/api/get_config',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Convex '+request.adminKey},body:JSON.stringify({adminKey:request.adminKey})});
if (!response.ok) throw Error(`Live config check HTTP ${response.status}`);
const live=await response.json();
const signature=(data:any)=>JSON.stringify(data.modules.map((m:any)=>[m.path,createHash('sha256').update(m.source).update(m.sourceMap||'').digest('hex')]).sort());
if (signature(live)!==signature(baseline)) throw Error('Production code changed since baseline: refusing to overwrite it');
request.dryRun=dryRun;
const options={url,adminKey:request.adminKey,deploymentName,deploymentType:'prod' as const,dryRun,message:'Repair hosted narration dispatch and error recovery; preserve unrelated production modules'};
async function api(path:string, data:any, compress=false) {
 const body=Buffer.from(JSON.stringify(data));
 const r=await fetch(url+path,{method:'POST',headers:{Authorization:'Convex '+request.adminKey,'Content-Type':'application/json','Convex-Client':'npm-1.46.0',...(compress?{'Content-Encoding':'br'}:{})},body:compress?brotliCompressSync(body):body});
 const d=await r.json();
 if(!r.ok) throw Error(`${path}: HTTP ${r.status}, code ${d.code??'unknown'}, detail ${String(d.message??'').replaceAll(request.adminKey,'[redacted]').slice(0,800)}`);
 return d;
}
const started=await api('/api/deploy2/start_push',request,true);
for (const diff of Object.values(started.schemaChange.indexDiffs??{}) as any[]) {
 if (diff.added_indexes.length || diff.removed_indexes.length) throw Error('Unexpected index change: refusing to finalize');
}
let complete=false;
for(let attempt=0;attempt<30;attempt++) {
 const state=await api('/api/deploy2/wait_for_schema',{adminKey:request.adminKey,schemaChange:started.schemaChange,timeoutMs:10000,dryRun});
 if(state.type==='complete'){complete=true;break;}
 if(state.type!=='inProgress')throw Error(`Schema state ${state.type}`);
}
if(!complete)throw Error('Schema validation did not finish within 5 minutes');
const result=await api('/api/deploy2/finish_push',{adminKey:request.adminKey,startPush:started,dryRun,message:options.message},true);
writeFileSync(`${base}/${name}-${dryRun?'dryrun':'deployed'}-result.json`,JSON.stringify(result,null,2));
console.log(JSON.stringify({target:deploymentName,dryRun,changedModules:request.appDefinition.changedModules.map((m:any)=>m.path),preservedRootModules:request.appDefinition.unchangedModuleHashes.length,result}));

